'use strict';

// ============================================================
// Safety - Controle de Equipamentos V1
// ============================================================
const CFG = window.SAFETY_CE_CONFIG;
firebase.initializeApp(CFG.firebase);
const auth = firebase.auth();
const db = firebase.firestore();
auth.setPersistence(firebase.auth.Auth.Persistence.LOCAL).catch(()=>null);

const C = name => `${CFG.prefix}${name}`;
const COLS = {
  clientes:C('clientes'), equipamentos:C('equipamentos'), categorias:C('categorias'),
  solicitacoes:C('solicitacoes'), locacoes:C('locacoes'), assistencias:C('assistencias'),
  cobrancas:C('cobrancas'), documentos:C('documentos'), usuarios:C('usuarios'),
  auditoria:C('auditoria'), testes:C('testes'), vistorias:C('vistorias'),
  movimentos:C('movimentos'), fabricantes:C('fabricantes'), configuracoes:C('configuracoes')
};

let currentUser = null;
let currentPage = 'dashboard';
let data = {
  clientes:[], equipamentos:[], categorias:[], solicitacoes:[], locacoes:[], assistencias:[],
  cobrancas:[], documentos:[], usuarios:[], auditoria:[], testes:[], vistorias:[],
  movimentos:[], fabricantes:[], configuracoes:[]
};
let signatureTarget = null;
let signatureDrawing = false;
let signatureLast = null;
let signatureStrokes = [];
let signatureCurrentStroke = null;
let signatureCaptureSize = {w:0,h:0};

const NAV = [
  ['dashboard','⌂','Dashboard'],['solicitacoes','✉','Solicitações'],['clientes','◉','Clientes'],
  ['equipamentos','▣','Equipamentos'],['locacoes','⇄','Locações'],['assistencias','⚙','Assistência Técnica'],
  ['cobrancas','R$','Cobranças'],['documentos','▤','Documentos'],['usuarios','♙','Usuários'],
  ['configuracoes','⚒','Configurações'],['auditoria','⌕','Auditoria']
];
const PAGE_TITLES = Object.fromEntries(NAV.map(x=>[x[0],x[2]]));

const $ = id => document.getElementById(id);
const nowISO = () => new Date().toISOString();
const todayISO = () => new Date().toISOString().slice(0,10);
const esc = s => String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]));
const brl = v => Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const num = v => Number(String(v??0).replace(/\./g,'').replace(',','.'))||0;
const dateBR = d => !d ? '—' : new Date((String(d).length===10?`${d}T12:00:00`:d)).toLocaleDateString('pt-BR');
const dateTimeBR = d => !d ? '—' : new Date(d).toLocaleString('pt-BR');
const monthKey = d => (d||todayISO()).slice(0,7);
const normalize = s => String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const uid6 = () => Math.random().toString(36).slice(2,8).toUpperCase();
const find = (arr,id) => data[arr].find(x=>x.id===id);
const active = arr => (data[arr]||[]).filter(x=>showArchivedRecords ? x?.excluido!==true : !(x?.arquivado===true || x?.ativo===false || x?.excluido===true));
const clone = o => JSON.parse(JSON.stringify(o));

function toast(msg,type='ok'){
  const t=$('toast'); t.textContent=msg; t.className=`toast ${type}`; t.classList.remove('hidden');
  clearTimeout(window.__toastTimer); window.__toastTimer=setTimeout(()=>t.classList.add('hidden'),3500);
}
function tag(text,type='info'){return `<span class="tag ${type}">${esc(text)}</span>`}
function statusType(s=''){
  s=normalize(s); if(/pago|disponivel|aprovad|liberad|concluid|entregue/.test(s))return'ok';
  if(/vencid|inadimpl|reprov|cancel|baixad|defeito/.test(s))return'danger';
  if(/aguard|reserv|manutenc|teste|orcamento|emprestad|aberto/.test(s))return'warn'; return'info';
}
function empty(msg='Nenhum registro encontrado.'){return `<div class="empty">${esc(msg)}</div>`}
function selectOptions(items,value,labelFn){return items.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(labelFn(x))}</option>`).join('')}
function monthLabel(k){ if(!k)return'—'; const [y,m]=k.split('-'); return new Date(Number(y),Number(m)-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'}).replace(/^./,c=>c.toUpperCase()) }
function daysBetween(a,b){if(!a||!b)return 0; return Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000)}
function dueDateForMonth(ym,day=15){const [y,m]=ym.split('-').map(Number),last=new Date(y,m,0).getDate(),d=Math.min(Math.max(Number(day||15),1),last);return `${ym}-${String(d).padStart(2,'0')}`}
function parseList(s){return String(s||'').split(/\n|;/).map(x=>x.trim()).filter(Boolean)}
function fileSafe(s){return normalize(s).replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'')||'documento'}
function clientName(id){return find('clientes',id)?.nomeRazao||'Cliente não encontrado'}
function equipName(id){const e=find('equipamentos',id);return e?`${e.tipo||e.categoriaNome||'Equipamento'} ${e.marca||''} ${e.modelo||''} · Série ${e.serial||'—'}`.replace(/\s+/g,' ').trim():'Equipamento não encontrado'}
function categoryName(id){return find('categorias',id)?.nome||'—'}
function userName(uid){return find('usuarios',uid)?.nome||uid||'—'}
function configDoc(){return data.configuracoes.find(x=>x.id==='geral')||{id:'geral',baseStatus:'implantacao',diasAlertaContrato:30,diasAlertaPreventiva:15}}

async function addDoc(col,obj){const ref=await db.collection(col).add({...obj,criadoEm:obj.criadoEm||nowISO(),criadoPor:obj.criadoPor||currentUser?.uid||'publico'});return ref.id}
async function setDoc(col,id,obj,merge=true){await db.collection(col).doc(id).set({...obj,alteradoEm:nowISO(),alteradoPor:currentUser?.uid||'publico'},{merge});}
async function deleteDocSoft(col,id){await setDoc(col,id,{excluido:true});}

async function audit(action,module,itemId,summary,before=null,after=null){
  if(!currentUser)return;
  try{await db.collection(COLS.auditoria).add({action,module,itemId,summary,before:before?JSON.stringify(before):null,after:after?JSON.stringify(after):null,uid:currentUser.uid,nome:currentUser.nome,em:nowISO()})}catch(e){console.warn('auditoria',e)}
}

// ============================================================
// Autenticação e inicialização
// ============================================================
function mostrarRecuperacao(){$('telaLogin').classList.add('hidden');$('telaRecuperar').classList.remove('hidden')}
function voltarLogin(){$('telaRecuperar').classList.add('hidden');$('telaLogin').classList.remove('hidden')}
async function enviarRecuperacao(){
  const email=$('eRecuperar').value.trim(),msg=$('msgRecuperar');
  try{await auth.sendPasswordResetEmail(email);msg.textContent='Link enviado para o e-mail informado.'}catch(e){msg.textContent='Não foi possível enviar: '+e.message}
}
async function fazerLogin(){
  const email=$('u').value.trim(),senha=$('p').value,msg=$('msgLogin'); msg.textContent='Entrando...';
  try{await auth.signInWithEmailAndPassword(email,senha)}catch(e){msg.textContent='Falha no login: '+friendlyAuthError(e)}
}
function friendlyAuthError(e){
  const c=e?.code||''; if(c.includes('invalid-credential')||c.includes('wrong-password')||c.includes('user-not-found'))return'E-mail ou senha inválidos.';
  if(c.includes('too-many-requests'))return'Muitas tentativas. Aguarde e tente novamente.'; return e.message||'Erro de autenticação.'
}
async function sair(){if(currentUser)await audit('logout','Sistema','sessao','Logout realizado.');await auth.signOut()}

async function authorize(user){
  const ce=await db.collection(COLS.usuarios).doc(user.uid).get().catch(()=>null);
  const ceData=ce?.exists?ce.data():null;
  if(!ce?.exists||ceData?.ativo===false)throw new Error('Seu usuário ainda não foi habilitado no Safety - Controle de Equipamentos.');
  const nome=ceData?.nome||user.displayName||user.email;
  return {uid:user.uid,email:user.email,nome,admin:ceData?.admin===true,ativo:true};
}
async function carregarDados(){
  const map=[['clientes',COLS.clientes],['equipamentos',COLS.equipamentos],['categorias',COLS.categorias],['solicitacoes',COLS.solicitacoes],['locacoes',COLS.locacoes],['assistencias',COLS.assistencias],['cobrancas',COLS.cobrancas],['documentos',COLS.documentos],['usuarios',COLS.usuarios],['auditoria',COLS.auditoria],['testes',COLS.testes],['vistorias',COLS.vistorias],['movimentos',COLS.movimentos],['fabricantes',COLS.fabricantes],['configuracoes',COLS.configuracoes]];
  const results=await Promise.all(map.map(async ([k,c])=>{try{const s=await db.collection(c).get();return[k,s.docs.map(d=>({id:d.id,...d.data()}))]}catch(e){console.warn(c,e);return[k,[]]}}));
  results.forEach(([k,v])=>data[k]=v);
  await bootstrapDefaults();
}
async function bootstrapDefaults(){
  if(!currentUser)return;
  if(!data.configuracoes.some(x=>x.id==='geral')){await db.collection(COLS.configuracoes).doc('geral').set({baseStatus:'implantacao',diasAlertaContrato:30,diasAlertaPreventiva:15,criadoEm:nowISO(),criadoPor:currentUser.uid});data.configuracoes.push({id:'geral',baseStatus:'implantacao',diasAlertaContrato:30,diasAlertaPreventiva:15})}
  if(!data.usuarios.some(x=>x.id===currentUser.uid)){
    await db.collection(COLS.usuarios).doc(currentUser.uid).set({nome:currentUser.nome,email:currentUser.email,ativo:true,admin:currentUser.admin,criadoEm:nowISO()},{merge:true});
    data.usuarios.push({id:currentUser.uid,nome:currentUser.nome,email:currentUser.email,ativo:true,admin:currentUser.admin});
  }
}
auth.onAuthStateChanged(async user=>{
  if(new URLSearchParams(location.search).get('solicitar')==='1'){await initPublicRequest();return}
  if(!user){currentUser=null;$('login').classList.remove('hidden');$('appShell').classList.add('hidden');return}
  const msg=$('msgLogin'); try{msg.textContent='Carregando dados...';currentUser=await authorize(user);await carregarDados();$('login').classList.add('hidden');$('appShell').classList.remove('hidden');$('userName').textContent=currentUser.nome;$('userAvatar').textContent=(currentUser.nome||'S').charAt(0).toUpperCase();renderNav();render();await audit('login','Sistema','sessao','Login realizado no Safety - Controle de Equipamentos.');msg.textContent=''}catch(e){msg.textContent=e.message;await auth.signOut()}
});

// ============================================================
// Navegação / modal
// ============================================================
function renderNav(){ $('nav').innerHTML=NAV.map(([id,ico,label])=>`<button class="nav-item ${currentPage===id?'active':''}" onclick="go('${id}')"><span class="nav-icon">${ico}</span>${label}</button>`).join('') }
function go(page){currentPage=page;renderNav();render();fecharMenu()}
function render(){ $('pageTitle').textContent=PAGE_TITLES[currentPage]||'Safety'; const views={dashboard:viewDashboard,solicitacoes:viewSolicitacoes,clientes:viewClientes,equipamentos:viewEquipamentos,locacoes:viewLocacoes,assistencias:viewAssistencias,cobrancas:viewCobrancas,documentos:viewDocumentos,usuarios:viewUsuarios,configuracoes:viewConfiguracoes,auditoria:viewAuditoria}; $('main').innerHTML=(views[currentPage]||viewDashboard)() }
function toggleMenu(){$('sidebar').classList.toggle('open');$('sidebarBackdrop').classList.toggle('open')}
function fecharMenu(){$('sidebar').classList.remove('open');$('sidebarBackdrop').classList.remove('open')}
function abrirModal(title,body,foot=''){$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modalFoot').innerHTML=foot||`<button class="btn ghost" onclick="fecharModal()">Fechar</button>`;$('modal').classList.remove('hidden');$('modal').setAttribute('aria-hidden','false')}
function fecharModal(){$('modal').classList.add('hidden');$('modal').setAttribute('aria-hidden','true');$('modalBody').innerHTML='';$('modalFoot').innerHTML=''}

// ============================================================
// Dashboard
// ============================================================
function paymentStatus(c){
  if(c.pagoEm){const p=c.pagoEm.slice(0,10);if(p<c.vencimento)return'Pago antes do vencimento';if(p===c.vencimento)return'Pago no vencimento';return'Pago após o vencimento'}
  if(todayISO()>c.vencimento)return'Inadimplente'; return'A vencer';
}
function viewDashboard(){
  const eq=active('equipamentos'), loc=active('locacoes').filter(x=>!['Encerrada','Cancelada'].includes(x.status)), ass=active('assistencias').filter(x=>!['Entregue','Cancelada'].includes(x.status));
  const mes=monthKey(), cb=active('cobrancas').filter(x=>x.competencia===mes), pagos=cb.filter(x=>x.pagoEm), inad=cb.filter(x=>paymentStatus(x)==='Inadimplente'), aberto=cb.filter(x=>!x.pagoEm), cfg=configDoc();
  const faturamento=cb.reduce((s,x)=>s+Number(x.valor||0),0), recebido=pagos.reduce((s,x)=>s+Number(x.valorPago||x.valor||0),0);
  const vencendo=loc.filter(x=>x.termino && daysBetween(todayISO(),x.termino)>=0 && daysBetween(todayISO(),x.termino)<=Number(cfg.diasAlertaContrato||30));
  return `<div class="notice ${cfg.baseStatus==='implantacao'?'':'blue'}">${cfg.baseStatus==='implantacao'?'<b>Base em implantação.</b> Indicadores financeiros e quantitativos são parciais até todos os clientes, equipamentos e locações ativas serem cadastrados.':'<b>Base operacional.</b> Indicadores calculados a partir dos registros ativos do sistema.'}</div>
  <div class="kpis">
    ${kpi('Equipamentos disponíveis',eq.filter(x=>x.situacao==='Disponível').length,'Prontos para locação')}
    ${kpi('Equipamentos alugados',eq.filter(x=>x.situacao==='Alugado').length,'Em contratos ativos')}
    ${kpi('Em manutenção/teste',eq.filter(x=>/manutenção|teste|liberação/i.test(x.situacao||'')).length,'Indisponíveis temporariamente')}
    ${kpi('Novas solicitações',active('solicitacoes').filter(x=>x.status==='Nova').length,'Aguardando análise',"go('solicitacoes')")}
  </div>
  <div class="card"><div class="row" style="align-items:flex-start"><div><h2>Cobranças — ${monthLabel(mes)}</h2><p class="hint">Situação mensal das locações. O status é calculado pela data de vencimento e pela data real do pagamento.</p></div><div class="inline-actions" style="justify-content:flex-end"><button class="btn ghost" onclick="go('cobrancas')">Abrir cobranças</button></div></div>
    <div class="metric-row">
      <div class="metric"><span>Clientes/cobranças</span><strong>${cb.length}</strong></div>
      <div class="metric"><span>Pagos</span><strong>${pagos.length}</strong></div>
      <div class="metric"><span>Falta pagar</span><strong>${aberto.length}</strong></div>
      <div class="metric"><span>Inadimplentes</span><strong>${inad.length}</strong></div>
      <div class="metric"><span>Previsto</span><strong>${brl(faturamento)}</strong></div>
      <div class="metric"><span>Recebido</span><strong>${brl(recebido)}</strong></div>
    </div>
  </div>
  <div class="split">
    <div class="card"><h3>Pendências operacionais</h3>${[
      ['Locações próximas do término',vencendo.length,`go('locacoes')`],['Assistências em andamento',ass.length,`go('assistencias')`],['Equipamentos reservados',eq.filter(x=>x.situacao==='Reservado').length,`go('equipamentos')`],['Cobranças inadimplentes',inad.length,`go('cobrancas')`]
    ].map(x=>`<div class="metric" style="margin-bottom:8px;cursor:pointer" onclick="${x[2]}"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div>
    <div class="card"><h3>Resumo de ativos</h3>${['Disponível','Reservado','Alugado','Emprestado','Aguardando teste','Em manutenção','Indisponível'].map(s=>`<div style="display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #edf0f3"><span>${s}</span><b>${eq.filter(x=>x.situacao===s).length}</b></div>`).join('')}</div>
  </div>`;
}
function kpi(label,value,sub,on=''){return `<div class="kpi ${on?'clickable':''}" ${on?`onclick="${on}"`:''}><div class="l">${label}</div><div class="v">${value}</div><div class="sub">${sub}</div></div>`}

// ============================================================
// Solicitação pública / pré-cadastro
// ============================================================
async function initPublicRequest(){
  $('login').classList.add('hidden');$('appShell').classList.add('hidden');$('publicRequest').classList.remove('hidden');
  let cats=[];try{const s=await db.collection(COLS.categorias).where('ativo','==',true).get();cats=s.docs.map(d=>({id:d.id,...d.data()}))}catch(e){console.warn(e)}
  $('publicRequest').innerHTML=publicRequestHtml(cats);
}
function publicRequestHtml(cats){
  return `<div class="public-shell"><div class="public-head"><img src="./assets/logo-safety-equipamentos.jpeg"><div><h1>Solicitação de Locação de Equipamento</h1><p>Preencha os dados abaixo. A solicitação será analisada pela equipe da Safety Equipamentos.</p></div></div>
  <form class="public-body" id="publicForm" onsubmit="enviarSolicitacaoPublica(event)">
    <div class="public-section"><h3>1. Identificação</h3><div class="grid2"><div><label>Tipo de cadastro *</label><select id="prTipo" required><option value="PF">Pessoa Física</option><option value="PJ">Pessoa Jurídica</option></select></div><div><label>Nome / Razão Social *</label><input id="prNome" required></div><div><label>CPF / CNPJ *</label><input id="prCpf" required></div><div><label>Responsável (quando comercial)</label><input id="prResp"></div><div><label>CPF do responsável</label><input id="prCpfResp"></div><div><label>Segmento</label><input id="prSegmento" placeholder="Odontologia, indústria, podologia, outro..."></div></div></div>
    <div class="public-section"><h3>2. Equipamento desejado</h3><div class="grid2"><div><label>Categoria / equipamento *</label><select id="prCategoria" required><option value="">Selecione</option>${cats.map(c=>`<option value="${esc(c.id)}">${esc(c.nome)}</option>`).join('')}<option value="outro">Outro / não listado</option></select></div><div><label>Descrição do equipamento</label><input id="prEquipDesc" placeholder="Ex.: autoclave 21 L, compressor, máquina de solda"></div><div><label>Quantidade *</label><input id="prQtd" type="number" min="1" value="1" required></div><div><label>Voltagem / característica</label><input id="prTensao" placeholder="127 V, 220 V, trifásico, etc."></div><div><label>Data pretendida de início</label><input id="prInicio" type="date"></div><div><label>Período pretendido</label><input id="prPeriodo" placeholder="30 dias, 12 meses, etc."></div></div><label>Observações / necessidade</label><textarea id="prObs"></textarea></div>
    <div class="public-section"><h3>3. Endereço de instalação</h3>${addressFields('prInst')}</div>
    <div class="public-section"><h3>4. Endereço cadastral / residencial</h3>${addressFields('prRes')}</div>
    <div class="public-section"><h3>5. Contatos</h3><div class="grid2"><div><label>Telefone principal *</label><input id="prTel" required></div><div><label>Telefone de referência</label><input id="prTelRef"></div><div><label>E-mail *</label><input id="prEmail" type="email" required></div><div><label>Como chegou até a Safety?</label><input id="prOrigem" placeholder="OLX, internet, indicação, propaganda..."></div></div></div>
    <div class="public-section"><h3>6. Confirmação</h3><p class="hint">A documentação necessária para formalização será solicitada posteriormente pela equipe da Safety Equipamentos.</p><div class="consent"><input id="prAceite" type="checkbox" required><label for="prAceite" style="margin:0">Confirmo que as informações acima são verdadeiras e autorizo a Safety Equipamentos a utilizá-las para análise da solicitação, contato e formalização da locação. O envio não garante reserva ou disponibilidade do equipamento.</label></div></div>
    <div class="form-actions"><a class="btn ghost" href="./index.html" style="display:inline-grid;place-items:center;text-decoration:none">Voltar</a><button class="btn" id="prSubmit">Enviar solicitação</button></div>
  </form></div>`;
}
function addressFields(p){return `<div class="grid3"><div><label>Logradouro</label><input id="${p}Log"></div><div><label>Número</label><input id="${p}Num"></div><div><label>Complemento</label><input id="${p}Comp"></div><div><label>Bairro</label><input id="${p}Bairro"></div><div><label>Município</label><input id="${p}Cidade"></div><div><label>UF</label><input id="${p}Uf" maxlength="2"></div><div><label>CEP</label><input id="${p}Cep"></div></div>`}
function readAddress(p){return {logradouro:$(`${p}Log`).value.trim(),numero:$(`${p}Num`).value.trim(),complemento:$(`${p}Comp`).value.trim(),bairro:$(`${p}Bairro`).value.trim(),cidade:$(`${p}Cidade`).value.trim(),uf:$(`${p}Uf`).value.trim().toUpperCase(),cep:$(`${p}Cep`).value.trim()}}
async function enviarSolicitacaoPublica(ev){
  ev.preventDefault(); const btn=$('prSubmit'); btn.disabled=true;btn.textContent='Enviando...';
  try{
    const obj={status:'Nova',tipoPessoa:$('prTipo').value,nomeRazao:$('prNome').value.trim(),cpfCnpj:$('prCpf').value.trim(),responsavel:$('prResp').value.trim(),cpfResponsavel:$('prCpfResp').value.trim(),segmento:$('prSegmento').value.trim(),categoriaId:$('prCategoria').value,equipamentoDescricao:$('prEquipDesc').value.trim(),quantidade:Number($('prQtd').value||1),tensao:$('prTensao').value.trim(),inicioPretendido:$('prInicio').value,periodoPretendido:$('prPeriodo').value.trim(),observacoes:$('prObs').value.trim(),enderecoInstalacao:readAddress('prInst'),enderecoResidencial:readAddress('prRes'),telefone:$('prTel').value.trim(),telefoneReferencia:$('prTelRef').value.trim(),email:$('prEmail').value.trim(),origem:$('prOrigem').value.trim(),aceiteEm:nowISO(),criadoEm:nowISO(),criadoPor:'publico'};
    const ref=db.collection(COLS.solicitacoes).doc();
    await ref.set(obj);
    if(CFG.requestNotificationWebhook){fetch(CFG.requestNotificationWebhook,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:ref.id,nome:obj.nomeRazao,equipamento:obj.equipamentoDescricao||obj.categoriaId,email:obj.email,telefone:obj.telefone})}).catch(()=>{})}
    $('publicRequest').innerHTML=`<div class="public-shell"><div class="public-body success-box"><div class="big">✓</div><h2>Solicitação enviada</h2><p>Obrigado. A equipe da Safety Equipamentos analisará os dados e entrará em contato.</p><p class="hint">Protocolo: ${ref.id}</p><a class="btn" href="./index.html" style="display:inline-grid;place-items:center;text-decoration:none;margin-top:16px">Concluir</a></div></div>`;
  }catch(e){alert('Não foi possível enviar a solicitação: '+e.message);btn.disabled=false;btn.textContent='Enviar solicitação'}
}

// ============================================================
// Solicitações internas
// ============================================================
function viewSolicitacoes(){
  const rows=active('solicitacoes').sort((a,b)=>(b.criadoEm||'').localeCompare(a.criadoEm||''));
  return `<div class="card"><div class="row" style="align-items:center"><div><h2>Solicitações de locação</h2><p class="hint">Pré-cadastros recebidos pelo formulário público. Podem ser convertidos em cliente sem redigitação.</p></div><div class="inline-actions" style="justify-content:flex-end"><a class="btn ghost" href="?solicitar=1" target="_blank" style="display:inline-grid;place-items:center;text-decoration:none">Abrir formulário público</a></div></div>
  ${rows.length?`<table><thead><tr><th>Recebida</th><th>Interessado</th><th>Equipamento</th><th>Contato</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${dateBR(s.criadoEm)}</td><td><b>${esc(s.nomeRazao)}</b><br><span class="muted">${esc(s.cpfCnpj||'')}</span></td><td>${esc(s.equipamentoDescricao||categoryName(s.categoriaId))}<br><span class="muted">${esc(s.periodoPretendido||'')}</span></td><td>${esc(s.telefone||'')}<br>${esc(s.email||'')}</td><td>${tag(s.status,statusType(s.status))}</td><td><div class="inline-actions"><button class="btn small ghost" onclick="detalharSolicitacao('${s.id}')">Abrir</button>${s.status!=='Convertida'?`<button class="btn small" onclick="converterSolicitacao('${s.id}')">Converter</button>`:''}</div></td></tr>`).join('')}</tbody></table>`:empty('Nenhuma solicitação recebida.')}</div>`;
}
function detalharSolicitacao(id){const s=find('solicitacoes',id); if(!s)return; abrirModal('Solicitação de locação',`<div class="grid2"><div><b>${esc(s.nomeRazao)}</b><p class="hint">${esc(s.tipoPessoa)} · ${esc(s.cpfCnpj)}</p></div><div>${tag(s.status,statusType(s.status))}</div></div><div class="section-title">Equipamento</div><p>${esc(s.equipamentoDescricao||categoryName(s.categoriaId))} · Qtd. ${s.quantidade||1} · ${esc(s.tensao||'sem especificação')}</p><p class="hint">Início: ${dateBR(s.inicioPretendido)} · Período: ${esc(s.periodoPretendido||'—')}</p><div class="section-title">Contatos</div><p>${esc(s.telefone||'—')} · ${esc(s.email||'—')} · Origem: ${esc(s.origem||'—')}</p><div class="section-title">Endereço de instalação</div><p>${esc(formatAddress(s.enderecoInstalacao))}</p><div class="section-title">Observações</div><p>${esc(s.observacoes||'—')}</p>`, `<button class="btn ghost" onclick="fecharModal()">Fechar</button><button class="btn ghost" onclick="alterarStatusSolicitacao('${id}')">Alterar status</button>${s.status!=='Convertida'?`<button class="btn" onclick="converterSolicitacao('${id}')">Converter em cliente</button>`:''}`)}
async function alterarStatusSolicitacao(id){const s=find('solicitacoes',id), st=prompt('Novo status: Nova, Em análise, Aguardando contato, Aprovada, Recusada, Arquivada',s?.status||'Nova');if(!st)return;await setDoc(COLS.solicitacoes,id,{status:st});await audit('status','Solicitações',id,`Solicitação alterada para ${st}.`);await refresh('Solicitação atualizada.')}
async function converterSolicitacao(id){
  const s=find('solicitacoes',id);if(!s)return;const existente=data.clientes.find(c=>normalize(c.cpfCnpj)===normalize(s.cpfCnpj)&&!c.excluido);
  if(existente){if(!confirm(`Já existe o cliente ${existente.nomeRazao}. Vincular esta solicitação a ele?`))return;await setDoc(COLS.solicitacoes,id,{status:'Convertida',clienteId:existente.id,convertidaEm:nowISO()});await audit('converter','Solicitações',id,`Solicitação vinculada ao cliente ${existente.nomeRazao}.`);await refresh('Solicitação vinculada ao cliente existente.');return}
  const obj={tipoPessoa:s.tipoPessoa||'PF',nomeRazao:s.nomeRazao,cpfCnpj:s.cpfCnpj,responsavel:s.responsavel||'',cpfResponsavel:s.cpfResponsavel||'',segmento:s.segmento||'',telefone:s.telefone||'',telefoneReferencia:s.telefoneReferencia||'',email:s.email||'',origem:s.origem||'',enderecoCadastral:s.enderecoResidencial||{},enderecosInstalacao:s.enderecoInstalacao?[s.enderecoInstalacao]:[],ativo:true,historicoCadastral:[]};
  const cid=await addDoc(COLS.clientes,obj);await setDoc(COLS.solicitacoes,id,{status:'Convertida',clienteId:cid,convertidaEm:nowISO()});await audit('converter','Solicitações',id,`Solicitação convertida em cliente ${obj.nomeRazao}.`);await refresh('Cliente criado a partir do pré-cadastro.');go('clientes')
}

