function viewCobrancas(){const mes=window.__cobMes||monthKey(),rows=active('cobrancas').filter(x=>x.competencia===mes).sort((a,b)=>(a.vencimento||'').localeCompare(b.vencimento||'')),paid=rows.filter(x=>x.pagoEm),open=rows.filter(x=>!x.pagoEm),late=rows.filter(x=>paymentStatus(x)==='Inadimplente');return `<div class="card"><div class="row" style="align-items:center"><div><h2>Cobranças</h2><p class="hint">Controle manual na V1. A integração automática com o Itaú fica preparada para a V2.</p></div><div class="inline-actions" style="justify-content:flex-end"><button class="btn ghost" onclick="gerarCobrancasMes('${mes}')">Gerar cobranças do mês</button><button class="btn" onclick="editarCobranca('', '${mes}')">+ Nova cobrança</button></div></div><div class="toolbar"><div><label>Competência</label><input type="month" value="${mes}" onchange="window.__cobMes=this.value;render()"></div></div><div class="metric-row"><div class="metric"><span>Total</span><strong>${rows.length}</strong></div><div class="metric"><span>Pagos</span><strong>${paid.length}</strong></div><div class="metric"><span>Falta pagar</span><strong>${open.length}</strong></div><div class="metric"><span>Inadimplentes</span><strong>${late.length}</strong></div><div class="metric"><span>Previsto</span><strong>${brl(rows.reduce((s,x)=>s+Number(x.valor||0),0))}</strong></div><div class="metric"><span>Recebido</span><strong>${brl(paid.reduce((s,x)=>s+Number(x.valorPago||x.valor||0),0))}</strong></div></div>${rows.length?`<table><thead><tr><th>Cliente</th><th>Locação</th><th>Valor</th><th>Vencimento</th><th>Pagamento</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${rows.map(c=>`<tr><td><b>${esc(clientName(c.clienteId))}</b></td><td>${esc(c.locacaoId||'Manual')}</td><td>${brl(c.valor)}</td><td>${dateBR(c.vencimento)}</td><td>${dateBR(c.pagoEm)}${c.pagoEm?`<br><span class="muted">${brl(c.valorPago||c.valor)}</span>`:''}</td><td>${tag(paymentStatus(c),statusType(paymentStatus(c)))}</td><td><div class="inline-actions">${!c.pagoEm?`<button class="btn small" onclick="registrarPagamento('${c.id}')">Registrar pagamento</button>`:`<button class="btn small ghost" onclick="estornarPagamento('${c.id}')">Estornar</button>`}<button class="btn small ghost" onclick="editarCobranca('${c.id}','${mes}')">Editar</button></div></td></tr>`).join('')}</tbody></table>`:empty('Nenhuma cobrança nesta competência.')}</div>`}
function editarCobranca(id='',mes=monthKey()){const c=id?find('cobrancas',id):{};abrirModal(id?'Editar cobrança':'Nova cobrança',`<div class="grid2"><div><label>Cliente *</label><select id="cbCli"><option value="">Selecione</option>${selectOptions(active('clientes'),c.clienteId,x=>x.nomeRazao)}</select></div><div><label>Locação</label><select id="cbLoc"><option value="">Sem vínculo</option>${selectOptions(active('locacoes'),c.locacaoId,l=>clientName(l.clienteId)+' · '+dateBR(l.inicio))}</select></div><div><label>Competência</label><input id="cbComp" type="month" value="${esc(c.competencia||mes)}"></div><div><label>Vencimento *</label><input id="cbVenc" type="date" value="${esc(c.vencimento||'')}"></div><div><label>Valor *</label><input id="cbValor" value="${esc(c.valor||'')}"></div><div><label>Observação</label><input id="cbObs" value="${esc(c.observacao||'')}"></div></div>`, `<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarCobranca('${id}')">Salvar</button>`)}
async function salvarCobranca(id){const cli=$('cbCli').value,venc=$('cbVenc').value,valor=num($('cbValor').value);if(!cli||!venc||!valor)return alert('Informe cliente, vencimento e valor.');const obj={clienteId:cli,locacaoId:$('cbLoc').value,competencia:$('cbComp').value,vencimento:venc,valor,observacao:$('cbObs').value.trim(),ativo:true};if(id){await setDoc(COLS.cobrancas,id,obj);await audit('editar','Cobranças',id,`Cobrança ${obj.competencia} atualizada.`)}else{const nid=await addDoc(COLS.cobrancas,obj);await audit('criar','Cobranças',nid,`Cobrança ${obj.competencia} criada.`)}fecharModal();await refresh('Cobrança salva.')}
function registrarPagamento(id){const c=find('cobrancas',id);abrirModal('Registrar pagamento',`<p><b>${esc(clientName(c.clienteId))}</b> · ${brl(c.valor)}</p><div class="grid2"><div><label>Data real do pagamento *</label><input id="pgData" type="date" value="${todayISO()}"></div><div><label>Valor pago</label><input id="pgValor" value="${esc(c.valor)}"></div></div><label>Observação</label><textarea id="pgObs"></textarea>`, `<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarPagamento('${id}')">Confirmar</button>`)}
async function salvarPagamento(id){const d=$('pgData').value;if(!d)return;await setDoc(COLS.cobrancas,id,{pagoEm:d,valorPago:num($('pgValor').value),observacaoPagamento:$('pgObs').value.trim()});const c=find('cobrancas',id);await audit('pagamento','Cobranças',id,`Pagamento registrado em ${dateBR(d)}.`);fecharModal();await refresh('Pagamento registrado.')}
async function estornarPagamento(id){if(!confirm('Remover a informação de pagamento desta cobrança?'))return;await setDoc(COLS.cobrancas,id,{pagoEm:null,valorPago:null,observacaoPagamento:''});await audit('estorno','Cobranças',id,'Pagamento estornado.');await refresh('Pagamento estornado.')}
async function gerarCobrancasMes(mes){
  const locs=active('locacoes').filter(l=>l.status==='Ativa'&&(!l.inicio||l.inicio.slice(0,7)<=mes)&&(!l.termino||l.termino.slice(0,7)>=mes));let n=0;
  for(const l of locs){if(data.cobrancas.some(c=>c.locacaoId===l.id&&c.competencia===mes&&!c.excluido))continue;const valor=(l.itens||[]).reduce((s,i)=>s+Number(i.valorMensal||0),0);if(!valor)continue;const due=dueDateForMonth(mes,l.diaVencimento||15);await addDoc(COLS.cobrancas,{clienteId:l.clienteId,locacaoId:l.id,competencia:mes,vencimento:due,valor,observacao:'Gerada a partir da locação ativa.',ativo:true});n++}
  await refresh(`${n} cobrança(s) gerada(s).`)
}

