function isAdmin(){return !!currentUser?.admin || currentUser?.perfil==='administrativo'}
function canAccessPage(page){return !ADMIN_ONLY_PAGES.has(page) || isAdmin()}
function requireOnline(){if(!navigator.onLine)throw new Error('Sem conexão com a internet. Esta operação não foi enviada ao servidor. Reconecte-se e tente novamente.')}
function isArchived(x){return x?.arquivado===true || x?.ativo===false || x?.excluido===true}
function allRecords(arr){return (data[arr]||[]).filter(x=>x?.excluido!==true)}
function userProfileLabel(){return isAdmin()?'Administrativo':'Técnico / Operacional'}
function userName(uid){if(uid===currentUser?.uid)return currentUser.nome;return (data.usuarios||[]).find(x=>x.id===uid)?.nome||uid||'—'}
function normalizeDoc(v){return normalize(String(v||'').replace(/[^a-zA-Z0-9]/g,''))}
function normalizedPhone(v){return String(v||'').replace(/\D/g,'')}
function equipName(id){const e=find('equipamentos',id);if(!e)return'Equipamento não encontrado';const cat=e.categoriaNome||categoryName(e.categoriaId)||e.tipo||'Equipamento';return [cat,e.modelo,e.marca,`Série ${e.serial||'—'}`,e.tensao].filter(Boolean).join(' · ')}
function protocolOf(x,fallback='—'){return x?.protocolo||fallback}
function modelTypeLabel(t){return ({contrato_locacao:'Contrato de Locação',comprovante_entrega:'Comprovante de Entrega',entrada_assistencia:'Comprovante de Entrada',termo_emprestimo:'Termo de Empréstimo',termo_substituicao:'Termo de Substituição',aditivo_responsavel:'Aditivo de Alteração de Responsável',orcamento:'Orçamento',relatorio_manutencao:'Relatório de Manutenção',recibo:'Recibo'})[t]||t}
function filterSelectOptions(id,q){const n=normalize(q),sel=$(id);if(!sel)return;[...sel.options].forEach((o,i)=>{if(i===0)return;o.hidden=!!n&&!normalize(o.textContent).includes(n)});if(sel.selectedOptions[0]?.hidden)sel.value=''}
function searchSelectHtml(searchId,selectId,optionsHtml,placeholder='Pesquisar...'){return `<input class="search compact" id="${searchId}" placeholder="${esc(placeholder)}" oninput="filterSelectOptions('${selectId}',this.value)"><select id="${selectId}">${optionsHtml}</select>`}
function allowedNext(current,map){return [current,...(map[current]||[])].filter(Boolean)}
function validateTransition(before,next,map,label='status'){if(!before||before===next)return true;if(!(map[before]||[]).includes(next)){alert(`Transição de ${label} não permitida: ${before} → ${next}.`);return false}return true}

async function addDoc(col,obj){requireOnline();const ref=await db.collection(col).add({...obj,criadoEm:obj.criadoEm||nowISO(),criadoPor:obj.criadoPor||currentUser?.uid||'publico'});return ref.id}
async function setDoc(col,id,obj,merge=true){requireOnline();await db.collection(col).doc(id).set({...obj,alteradoEm:nowISO(),alteradoPor:currentUser?.uid||'publico'},{merge})}
async function audit(action,module,itemId,summary,before=null,after=null){if(!currentUser||!navigator.onLine)return;try{await db.collection(COLS.auditoria).add({action,module,itemId,summary,before:before?JSON.stringify(before):null,after:after?JSON.stringify(after):null,uid:currentUser.uid,nome:currentUser.nome,em:nowISO()})}catch(e){console.warn('auditoria',e)}}
async function nextProtocol(kind){requireOnline();const year=new Date().getFullYear(),ref=db.collection(COLS.contadores).doc(`${kind}_${year}`);return db.runTransaction(async tx=>{const s=await tx.get(ref),next=(s.exists?Number(s.data().next||1):1);tx.set(ref,{kind,year,next:next+1,alteradoEm:nowISO()},{merge:true});return `${kind}-${year}-${String(next).padStart(6,'0')}`})}

async function authorize(user){
  const ce=await db.collection(COLS.usuarios).doc(user.uid).get().catch(()=>null),d=ce?.exists?ce.data():null;
  if(!ce?.exists||d?.ativo===false)throw new Error('Seu usuário ainda não foi habilitado no Safety - Controle de Equipamentos.');
  const perfil=d.perfil||(d.admin===true?'administrativo':'tecnico');
  return {uid:user.uid,email:user.email,nome:d.nome||user.displayName||user.email,admin:d.admin===true||perfil==='administrativo',perfil,funcao:d.funcao||'',matricula:d.matricula||'',ativo:true};
}
async function carregarColecao(k,col,queryBuilder=null){try{let q=db.collection(col);if(queryBuilder)q=queryBuilder(q);const s=await q.get();data[k]=s.docs.map(d=>({id:d.id,...d.data()}))}catch(e){console.warn(col,e);data[k]=[]}}
async function carregarDados(){
  const common=[['clientes',COLS.clientes],['equipamentos',COLS.equipamentos],['categorias',COLS.categorias],['assistencias',COLS.assistencias],['testes',COLS.testes],['vistorias',COLS.vistorias],['fabricantes',COLS.fabricantes],['configuracoes',COLS.configuracoes],['modelosDocumentos',COLS.modelosDocumentos]];
  await Promise.all(common.map(([k,c])=>carregarColecao(k,c)));
  if(isAdmin()){
    await Promise.all([carregarColecao('solicitacoes',COLS.solicitacoes),carregarColecao('locacoes',COLS.locacoes),carregarColecao('cobrancas',COLS.cobrancas),carregarColecao('documentos',COLS.documentos),carregarColecao('movimentos',COLS.movimentos),carregarColecao('usuarios',COLS.usuarios),carregarColecao('auditoria',COLS.auditoria)]);
  }else{
    data.solicitacoes=[];data.locacoes=[];data.cobrancas=[];data.auditoria=[];
    await Promise.all([
      carregarColecao('documentos',COLS.documentos,q=>q.where('sigiloFinanceiro','==',false)),
      carregarColecao('movimentos',COLS.movimentos,q=>q.where('sigiloFinanceiro','==',false))
    ]);
    try{const s=await db.collection(COLS.usuarios).doc(currentUser.uid).get();data.usuarios=s.exists?[{id:s.id,...s.data()}]:[]}catch(e){data.usuarios=[]}
  }
  await bootstrapDefaults();
}
async function bootstrapDefaults(){
  if(!currentUser)return;
  if(isAdmin()&&!data.configuracoes.some(x=>x.id==='geral')){const o={baseStatus:'implantacao',diasAlertaContrato:30,diasAlertaPreventiva:15,criadoEm:nowISO(),criadoPor:currentUser.uid};await db.collection(COLS.configuracoes).doc('geral').set(o);data.configuracoes.push({id:'geral',...o})}
  if(isAdmin()&&!data.configuracoes.some(x=>x.id==='publico')){const o={requestNotificationWebhook:CFG.requestNotificationWebhook||'',criadoEm:nowISO(),criadoPor:currentUser.uid};await db.collection(COLS.configuracoes).doc('publico').set(o);data.configuracoes.push({id:'publico',...o})}
  if(isAdmin()){
    const me=(data.usuarios||[]).find(x=>x.id===currentUser.uid);if(me&&(!me.perfil||me.matricula===undefined||me.funcao===undefined)){await db.collection(COLS.usuarios).doc(currentUser.uid).set({perfil:'administrativo',admin:true,matricula:me.matricula||'',funcao:me.funcao||'Administrativo',alteradoEm:nowISO()},{merge:true});Object.assign(me,{perfil:'administrativo',admin:true,matricula:me.matricula||'',funcao:me.funcao||'Administrativo'})}
    await ensureDefaultModels();
  }
}

function renderNav(){const allowed=NAV.filter(([id])=>canAccessPage(id));$('nav').innerHTML=allowed.map(([id,ico,label])=>`<button class="nav-item ${currentPage===id?'active':''}" onclick="go('${id}')"><span class="nav-icon">${ico}</span>${label}</button>`).join('')}
function go(page){if(!canAccessPage(page)){toast('Seu perfil não possui acesso a este módulo.','danger');return}currentPage=page;renderNav();render();fecharMenu()}
function render(){if(!canAccessPage(currentPage))currentPage='dashboard';$('pageTitle').textContent=PAGE_TITLES[currentPage]||'Safety';const views={dashboard:viewDashboard,solicitacoes:viewSolicitacoes,clientes:viewClientes,equipamentos:viewEquipamentos,locacoes:viewLocacoes,assistencias:viewAssistencias,cobrancas:viewCobrancas,documentos:viewDocumentos,usuarios:viewUsuarios,configuracoes:viewConfiguracoes,auditoria:viewAuditoria,modelos:viewModelosDocumentos};$('main').innerHTML=(views[currentPage]||viewDashboard)();const role=$('userRole');if(role)role.textContent=userProfileLabel()}

function connectionBadgeHtml(){return navigator.onLine?'<span class="conn online">Online</span>':'<span class="conn offline">Sem conexão</span>'}
function updateConnectionBadge(){const el=$('connectionBadge');if(el)el.innerHTML=connectionBadgeHtml();if(!navigator.onLine)toast('Sem conexão. Operações de gravação estão bloqueadas.','danger')}
window.addEventListener('online',updateConnectionBadge);window.addEventListener('offline',updateConnectionBadge);

function viewDashboard(){
  const eq=active('equipamentos'),ass=active('assistencias').filter(x=>!['Entregue','Cancelada'].includes(x.status)),cfg=configDoc();
  if(!isAdmin())return `<div class="notice ${cfg.baseStatus==='implantacao'?'':'blue'}">${cfg.baseStatus==='implantacao'?'<b>Base em implantação.</b>':'<b>Base operacional.</b>'} Painel operacional do perfil Técnico.</div><div class="kpis">${kpi('Equipamentos disponíveis',eq.filter(x=>x.situacao==='Disponível').length,'Prontos para uso')}${kpi('Aguardando teste',eq.filter(x=>x.situacao==='Aguardando teste').length,'Necessitam liberação')}${kpi('Em manutenção',eq.filter(x=>/manutenção|aguardando peça/i.test(x.situacao||'')).length,'Ativos indisponíveis')}${kpi('Assistências em andamento',ass.length,'Atendimentos abertos',"go('assistencias')")}</div><div class="card"><h3>Resumo operacional</h3>${['Disponível','Emprestado','Aguardando teste','Em manutenção','Aguardando peça','Indisponível'].map(s=>`<div class="metric"><span>${s}</span><strong>${eq.filter(x=>x.situacao===s).length}</strong></div>`).join('')}</div>`;
  const loc=active('locacoes').filter(x=>!RENTAL_CLOSED_STATUSES.has(x.status)),mes=monthKey(),cb=active('cobrancas').filter(x=>x.competencia===mes),pagos=cb.filter(x=>x.pagoEm),inad=cb.filter(x=>paymentStatus(x)==='Inadimplente'),aberto=cb.filter(x=>!x.pagoEm),faturamento=cb.reduce((s,x)=>s+Number(x.valorContrato||x.valor||0),0),recebido=pagos.reduce((s,x)=>s+Number(x.valorPago||x.valorAtualizado||x.valorContrato||x.valor||0),0),vencendo=loc.filter(x=>x.termino&&daysBetween(todayISO(),x.termino)>=0&&daysBetween(todayISO(),x.termino)<=Number(cfg.diasAlertaContrato||30));
  return `<div class="notice ${cfg.baseStatus==='implantacao'?'':'blue'}">${cfg.baseStatus==='implantacao'?'<b>Base em implantação.</b> Indicadores financeiros e quantitativos são parciais até a carga real ser concluída.':'<b>Base operacional.</b> Indicadores calculados a partir dos registros ativos.'}</div><div class="kpis">${kpi('Equipamentos disponíveis',eq.filter(x=>x.situacao==='Disponível').length,'Prontos para locação')}${kpi('Equipamentos alugados',eq.filter(x=>x.situacao==='Alugado').length,'Em contratos ativos')}${kpi('Em manutenção/teste',eq.filter(x=>/manutenção|teste|peça/i.test(x.situacao||'')).length,'Indisponíveis temporariamente')}${kpi('Novas solicitações',active('solicitacoes').filter(x=>x.status==='Nova').length,'Aguardando análise',"go('solicitacoes')")}</div><div class="card"><div class="row"><div><h2>Cobranças — ${monthLabel(mes)}</h2><p class="hint">Resumo financeiro mensal.</p></div><button class="btn ghost" onclick="go('cobrancas')">Abrir cobranças</button></div><div class="metric-row"><div class="metric"><span>Total</span><strong>${cb.length}</strong></div><div class="metric"><span>Pagos</span><strong>${pagos.length}</strong></div><div class="metric"><span>Falta pagar</span><strong>${aberto.length}</strong></div><div class="metric"><span>Inadimplentes</span><strong>${inad.length}</strong></div><div class="metric"><span>Previsto</span><strong>${brl(faturamento)}</strong></div><div class="metric"><span>Recebido</span><strong>${brl(recebido)}</strong></div></div></div><div class="split"><div class="card"><h3>Pendências operacionais</h3>${[['Locações próximas do término',vencendo.length,"go('locacoes')"],['Assistências em andamento',ass.length,"go('assistencias')"],['Equipamentos reservados',eq.filter(x=>x.situacao==='Reservado').length,"go('equipamentos')"],['Cobranças inadimplentes',inad.length,"go('cobrancas')"]].map(x=>`<div class="metric clickable" onclick="${x[2]}"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><div class="card"><h3>Resumo de ativos</h3>${['Disponível','Reservado','Alugado','Emprestado','Aguardando teste','Em manutenção','Indisponível'].map(s=>`<div class="metric"><span>${s}</span><strong>${eq.filter(x=>x.situacao===s).length}</strong></div>`).join('')}</div></div>`
}

function csvEscape(v){v=String(v??'');return /[;"\n]/.test(v)?`"${v.replace(/"/g,'""')}"`:v}
function exportarCSV(tipo){
  if(!isAdmin())return alert('Somente o perfil Administrativo pode exportar dados.');let head=[],rows=[];
  if(tipo==='clientes'){head=['tipo','nomeRazao','cpfCnpj','responsavel','telefone','email','segmento','status'];rows=allRecords('clientes').map(c=>[c.tipoPessoa,c.nomeRazao,c.cpfCnpj,c.responsavel,c.telefone,c.email,c.segmento,isArchived(c)?'Arquivado':'Ativo'])}
  if(tipo==='equipamentos'){head=['categoria','modelo','fabricante','serial','tensao','situacao','localAtual','status'];rows=allRecords('equipamentos').map(e=>[e.categoriaNome||categoryName(e.categoriaId),e.modelo,e.marca,e.serial,e.tensao,e.situacao,e.localAtual,isArchived(e)?'Arquivado':'Ativo'])}
  if(tipo==='locacoes'){head=['protocolo','cliente','inicio','termino','status','valorMensal'];rows=allRecords('locacoes').map(l=>[l.protocolo,clientName(l.clienteId),l.inicio,l.termino,l.status,(l.itens||[]).reduce((s,i)=>s+Number(i.valorMensal||0),0)])}
  if(tipo==='assistencias'){head=['protocolo','cliente','entrada','equipamento','serial','tipo','status'];rows=allRecords('assistencias').map(a=>[a.protocolo,clientName(a.clienteId),a.entrada,[a.equipamentoTipo,a.marca,a.modelo].filter(Boolean).join(' '),a.serial,a.tipoAtendimento,a.status])}
  if(tipo==='cobrancas'){head=['cliente','locacao','competencia','vencimento','valorContrato','valorAtualizado','valorPago','situacao'];rows=allRecords('cobrancas').map(c=>[clientName(c.clienteId),c.locacaoProtocolo||c.locacaoId,c.competencia,c.vencimento,c.valorContrato||c.valor,c.valorAtualizado||'',c.valorPago||'',paymentStatus(c)])}
  if(!head.length)return;const text='\ufeff'+[head,...rows].map(r=>r.map(csvEscape).join(';')).join('\n');downloadBlob(new Blob([text],{type:'text/csv;charset=utf-8'}),`safety_${tipo}_${todayISO()}.csv`);audit('exportar','Administração',tipo,`Exportação CSV de ${tipo}.`)
}
async function importarCSV(){alert('A importação em massa está desativada na V1 Definitiva. A base real será cadastrada manualmente, registro por registro.')}

const HOMOLOGATION_COLLECTIONS=['solicitacoes','clientes','equipamentos','locacoes','assistencias','cobrancas','documentos','testes','vistorias','movimentos'];
async function archivarDadosHomologacao(){
  if(!isAdmin())return;const phrase=prompt('Esta ação arquivará TODOS os registros operacionais atuais como dados de homologação. Digite ARQUIVAR TESTES para confirmar:');if(phrase!=='ARQUIVAR TESTES')return;
  requireOnline();let total=0;for(const k of HOMOLOGATION_COLLECTIONS){const col=COLS[k],items=(data[k]||[]).filter(x=>!x.arquivado);for(let i=0;i<items.length;i+=400){const batch=db.batch();items.slice(i,i+400).forEach(x=>batch.set(db.collection(col).doc(x.id),{arquivado:true,ativo:false,origem:'homologacao_v1',arquivadoEm:nowISO(),arquivadoPor:currentUser.uid},{merge:true}));await batch.commit();total+=Math.min(400,items.length-i)}}await db.collection(COLS.configuracoes).doc('geral').set({homologacaoArquivadaEm:nowISO(),homologacaoArquivadaPor:currentUser.uid},{merge:true});await audit('arquivar_homologacao','Configurações','homologacao',`${total} registros de homologação arquivados.`);await refresh(`${total} registros de teste foram arquivados.`)
}
async function reativarDadosHomologacao(){if(!isAdmin())return;if(!confirm('Reativar a massa de homologação? Faça isso apenas em ambiente de teste/V2.'))return;requireOnline();let total=0;for(const k of HOMOLOGATION_COLLECTIONS){const col=COLS[k],items=(data[k]||[]).filter(x=>x.origem==='homologacao_v1');for(let i=0;i<items.length;i+=400){const batch=db.batch();items.slice(i,i+400).forEach(x=>batch.set(db.collection(col).doc(x.id),{arquivado:false,ativo:true,reativadoEm:nowISO(),reativadoPor:currentUser.uid},{merge:true}));await batch.commit();total+=Math.min(400,items.length-i)}}await audit('reativar_homologacao','Configurações','homologacao',`${total} registros de homologação reativados.`);await refresh(`${total} registros de homologação reativados.`)}

const DEFAULT_CONTRACT_BODY = `CLÁUSULA 1ª — DO OBJETO E DA PROPRIEDADE
1.1. A LOCADORA cede temporariamente à LOCATÁRIA o uso dos equipamentos identificados no Quadro-Resumo e na tabela de equipamentos deste instrumento, permanecendo a propriedade integral dos bens com a LOCADORA.
1.2. A contratação não constitui venda, promessa de venda, arrendamento mercantil ou transferência de propriedade.
1.3. Cada equipamento será individualizado principalmente pelo número de série, que prevalecerá para fins de identificação, rastreabilidade, substituição e devolução.
1.4. Os acessórios entregues juntamente com cada equipamento integram a locação e deverão ser restituídos ao encerramento.

CLÁUSULA 2ª — DA ENTREGA, INSTALAÇÃO E ACEITE
2.1. A LOCADORA entregará o equipamento em condições adequadas de funcionamento, após os testes técnicos aplicáveis à sua categoria.
2.2. A entrega será registrada por comprovante, vistoria, checklist ou outro registro emitido pelo sistema da LOCADORA, contendo, quando aplicável, equipamento, número de série, acessórios, condição de entrega e assinaturas.
2.3. A LOCATÁRIA deverá providenciar, às suas expensas, instalações elétricas, hidráulicas, pneumáticas ou outras condições de infraestrutura necessárias ao correto funcionamento do equipamento, conforme especificações técnicas aplicáveis.
2.4. O início da locação ocorrerá na data registrada no Quadro-Resumo ou no comprovante de entrega/instalação, conforme definido na contratação.

CLÁUSULA 3ª — DO PRAZO E DA PRORROGAÇÃO
3.1. A locação vigorará pelo período indicado no Quadro-Resumo.
3.2. Qualquer prorrogação expressamente acordada será registrada pela LOCADORA, mantendo-se o histórico do prazo originalmente contratado e do novo término.
3.3. Findo o prazo determinado, caso a LOCATÁRIA permaneça com o equipamento e a LOCADORA não se oponha, a locação poderá ser considerada prorrogada por prazo indeterminado, mantendo-se as condições vigentes, sem prejuízo dos reajustes contratualmente previstos.
3.4. Na locação por prazo indeterminado, qualquer das partes poderá manifestar intenção de encerramento mediante comunicação escrita com antecedência mínima de 30 (trinta) dias, salvo prazo diferente expressamente estabelecido no Quadro-Resumo.

CLÁUSULA 4ª — DO VALOR, FATURAMENTO E PAGAMENTO
4.1. A LOCATÁRIA pagará os valores mensais indicados no Quadro-Resumo e na tabela de equipamentos.
4.2. Quando houver mais de um equipamento no mesmo contrato, poderão ser indicados valores individuais, sendo o valor mensal total correspondente à soma dos equipamentos vinculados à locação.
4.3. A primeira mensalidade será devida conforme a condição comercial registrada para a locação, podendo ocorrer na entrega ou instalação.
4.4. As demais cobranças serão realizadas por meio indicado pela LOCADORA, inclusive boleto bancário.
4.5. Eventual atraso operacional na emissão do boleto ou documento de cobrança não representará renúncia ao crédito, alteração definitiva da data contratual ou novação da obrigação.

CLÁUSULA 5ª — DO REAJUSTE
5.1. Nos contratos com duração igual ou superior a 12 (doze) meses, o valor da locação poderá ser reajustado uma vez a cada período de 12 (doze) meses.
5.2. O índice padrão será o IPCA/IBGE, salvo se outro índice lícito estiver expressamente definido no Quadro-Resumo.
5.3. Na extinção ou indisponibilidade definitiva do índice eleito, será utilizado outro índice oficial que melhor represente a variação inflacionária do período.

CLÁUSULA 6ª — DAS OBRIGAÇÕES DA LOCADORA
6.1. Compete à LOCADORA: entregar o equipamento em condições de servir à finalidade contratada; realizar, diretamente ou por pessoa autorizada, a manutenção decorrente de desgaste ou falha proveniente do uso normal; substituir peças e componentes compatíveis quando tecnicamente necessário; realizar os testes técnicos necessários após intervenções; manter registros técnicos, histórico de substituições e movimentações; e, quando operacionalmente possível, substituir temporária ou definitivamente equipamento que apresente defeito não imputável à LOCATÁRIA por equipamento equivalente ou compatível.

CLÁUSULA 7ª — DAS OBRIGAÇÕES DA LOCATÁRIA
7.1. Compete à LOCATÁRIA utilizar o equipamento exclusivamente para sua finalidade adequada e conforme orientações técnicas; conservar o equipamento e seus acessórios; não sublocar, emprestar, ceder ou transferir o equipamento a terceiros sem autorização escrita; não desmontar, modificar ou permitir manutenção por terceiros sem autorização; comunicar imediatamente defeitos, falhas, acidentes, danos ou ocorrências relevantes; permitir acesso de pessoal autorizado da LOCADORA para inspeções, manutenção, substituição ou retirada quando contratual ou legalmente cabível; manter o equipamento no endereço de instalação informado; pagar pontualmente os valores contratados; e devolver equipamento e acessórios ao término da locação.
7.2. A deterioração decorrente do uso regular e desgaste natural não será considerada dano imputável à LOCATÁRIA.

CLÁUSULA 8ª — DA MANUTENÇÃO, MAU USO E DESPESAS NÃO INCLUÍDAS
8.1. As manutenções necessárias em razão de falha técnica ou desgaste normal serão de responsabilidade da LOCADORA.
8.2. Poderão ser cobrados da LOCATÁRIA, mediante comprovação técnica, serviços, componentes e despesas decorrentes de mau uso, queda, impacto, instalação inadequada, intervenção não autorizada, uso de componentes ou consumíveis incompatíveis, alteração não autorizada ou negligência na conservação.
8.3. Sempre que possível, a LOCADORA comunicará previamente o diagnóstico e os custos atribuíveis à LOCATÁRIA.

CLÁUSULA 9ª — DA SUBSTITUIÇÃO DO EQUIPAMENTO
9.1. A LOCADORA poderá substituir equipamento por outro equivalente quando houver necessidade técnica, manutenção, indisponibilidade ou outro motivo operacional justificado.
9.2. Toda substituição deverá ser registrada, identificando equipamento anterior, equipamento substituto, números de série, data, motivo e responsável pela operação.
9.3. A substituição não importará em novação do contrato, salvo alteração expressa das condições comerciais.

CLÁUSULA 10ª — DA ALTERAÇÃO DE ENDEREÇO E RESPONSÁVEL
10.1. O equipamento não poderá ser transferido para outro endereço sem comunicação e autorização prévia da LOCADORA.
10.2. A alteração de endereço será registrada no histórico da locação.
10.3. A substituição da pessoa responsável por uma mesma LOCATÁRIA pessoa jurídica não implicará, por si só, novo contrato, devendo ser formalizada por registro ou termo aditivo.
10.4. Caso haja mudança efetiva do CPF ou CNPJ da parte contratante, a transferência dependerá de expressa aprovação da LOCADORA e poderá exigir encerramento do contrato existente e celebração de nova locação.

CLÁUSULA 11ª — DOS DANOS, FURTO, ROUBO, EXTRAVIO E SINISTROS
11.1. A LOCATÁRIA responderá pelos danos causados ao equipamento quando decorrentes de dolo, culpa, mau uso, negligência ou descumprimento das obrigações contratuais.
11.2. Não será cobrado como dano o desgaste natural decorrente do uso regular.
11.3. Em caso de furto, roubo, extravio, incêndio, acidente ou outro sinistro relevante, a LOCATÁRIA deverá comunicar imediatamente à LOCADORA e fornecer as informações e documentos disponíveis, inclusive registro policial quando cabível.
11.4. A responsabilidade financeira será apurada de acordo com as circunstâncias concretas, a legislação aplicável e a eventual participação ou culpa das partes.

CLÁUSULA 12ª — DA RESCISÃO ANTECIPADA
12.1. Durante o prazo determinado, a LOCATÁRIA poderá solicitar o encerramento antecipado da locação.
12.2. Salvo condição comercial específica registrada no Quadro-Resumo, a rescisão antecipada pela LOCATÁRIA estará sujeita a multa compensatória equivalente a 3 (três) mensalidades, reduzida proporcionalmente ao período já cumprido e limitada ao saldo das mensalidades que ainda venceriam.
12.3. A fórmula de proporcionalidade será: multa devida = 3 mensalidades × período restante ÷ período total originalmente contratado.
12.4. A multa não será exigida quando a resolução decorrer de descumprimento relevante da LOCADORA que impossibilite o uso regular do equipamento e não seja sanado em prazo razoável após comunicação.

CLÁUSULA 13ª — DA MORA E INADIMPLÊNCIA
13.1. O pagamento realizado após o vencimento ficará sujeito a multa moratória de 2% sobre o débito, juros de mora de 1% ao mês calculados proporcionalmente aos dias de atraso e atualização monetária pelo IPCA/IBGE quando aplicável.
13.2. O valor efetivamente atualizado poderá ser apresentado no boleto ou outro instrumento de cobrança.
13.3. Permanecendo a inadimplência por mais de 15 (quinze) dias, a LOCADORA poderá notificar a LOCATÁRIA para regularização.
13.4. Persistindo o inadimplemento após a notificação e prazo concedido, a LOCADORA poderá considerar o contrato rescindido, exigir a devolução do equipamento, promover cobrança extrajudicial ou judicial, protestar títulos regularmente constituídos e utilizar mecanismos legais de proteção ao crédito, observados os procedimentos previstos em lei.
13.5. É vedada cobrança em duplicidade pelo mesmo fato.

CLÁUSULA 14ª — DA DEVOLUÇÃO
14.1. Encerrada a locação, a LOCATÁRIA deverá disponibilizar o equipamento para devolução no prazo acordado.
14.2. A devolução será registrada pela LOCADORA, com conferência do número de série, acessórios e estado aparente.
14.3. O equipamento devolvido ficará sujeito a teste técnico antes de retornar ao estoque disponível.
14.4. Eventuais danos que ultrapassem o desgaste natural deverão ser tecnicamente identificados e documentados.

CLÁUSULA 15ª — DA NÃO DEVOLUÇÃO
15.1. Encerrado ou rescindido o contrato e formalmente solicitada a devolução, caso a LOCATÁRIA mantenha injustificadamente o equipamento em seu poder, continuará responsável pelo pagamento do valor de locação enquanto perdurar a retenção, sem prejuízo da apuração de danos eventualmente causados.
15.2. A LOCADORA poderá adotar as medidas judiciais cabíveis para restituição do equipamento.

CLÁUSULA 16ª — DAS MEDIDAS POSSESSÓRIAS
16.1. A retenção indevida, transferência não autorizada, ocultação ou recusa injustificada de restituição do equipamento poderá ensejar a adoção das medidas possessórias e judiciais cabíveis.
16.2. Eventual pedido de manutenção ou reintegração de posse observará os requisitos da legislação processual civil vigente.

CLÁUSULA 17ª — DA RECUPERAÇÃO JUDICIAL, FALÊNCIA OU INSOLVÊNCIA
17.1. A eventual recuperação judicial, falência ou situação de insolvência será tratada de acordo com a legislação específica vigente.
17.2. A decretação de falência, isoladamente, não implicará resolução automática do contrato quando a legislação determinar regime diverso.

CLÁUSULA 18ª — DA PROTEÇÃO DE DADOS PESSOAIS
18.1. Os dados pessoais relacionados a este contrato poderão ser tratados pela LOCADORA para elaboração e execução do contrato, cadastro e identificação das partes, faturamento, cobrança, assistência técnica, exercício regular de direitos, cumprimento de obrigações legais ou regulatórias e proteção do crédito quando aplicável.
18.2. Os dados poderão ser compartilhados, dentro da necessidade e finalidade aplicável, com instituições financeiras e meios de pagamento, prestadores técnicos, contabilidade, assessorias jurídicas, fabricantes, autoridades públicas ou outros operadores necessários à execução da relação contratual.
18.3. A LOCADORA adotará medidas razoáveis de segurança e limitará o tratamento aos dados necessários às finalidades legítimas, observados os direitos previstos na legislação vigente.

CLÁUSULA 19ª — DAS COMUNICAÇÕES
19.1. As partes reconhecem como meios válidos de comunicação operacional os telefones, WhatsApp e e-mails cadastrados.
19.2. É responsabilidade de cada parte manter seus dados de contato atualizados.
19.3. Comunicações relevantes, como solicitação de devolução, alteração de endereço, prorrogação, inadimplência ou rescisão, deverão permitir registro de envio e, quando necessário, confirmação ou comprovação de recebimento.

CLÁUSULA 20ª — DOS DOCUMENTOS E ASSINATURAS ELETRÔNICAS
20.1. As partes reconhecem como válidos os documentos e registros eletrônicos vinculados à locação, inclusive contratos, termos, comprovantes, checklists e assinaturas eletrônicas, observada a legislação vigente.
20.2. As assinaturas realizadas em dispositivo eletrônico poderão ser utilizadas como manifestação de vontade e elemento de comprovação de autoria, juntamente com registros eletrônicos de data, hora, usuário e documento correspondente.
20.3. Quando necessário maior nível de formalidade ou executividade, o instrumento poderá ser firmado com testemunhas ou por provedor de assinatura eletrônica adequado à legislação aplicável.

CLÁUSULA 21ª — DO CASO FORTUITO E DA FORÇA MAIOR
21.1. Nenhuma parte será responsabilizada pelo atraso ou impossibilidade de cumprimento decorrente de evento inevitável e alheio ao seu controle, na extensão em que caracterizado caso fortuito ou força maior.
21.2. A parte afetada deverá comunicar a outra tão logo seja razoavelmente possível e adotar medidas para reduzir os efeitos do evento.

CLÁUSULA 22ª — DA TOLERÂNCIA E NÃO RENÚNCIA
22.1. Eventual tolerância de uma parte quanto ao descumprimento de obrigação pela outra não constituirá novação, renúncia ou alteração definitiva do contrato.
22.2. Qualquer alteração relevante das condições contratuais deverá ser registrada por termo, aditivo ou nova versão documental aplicável à locação.

CLÁUSULA 23ª — DA LEGISLAÇÃO DE PROTEÇÃO AO CONSUMIDOR
23.1. Quando a relação jurídica concreta estiver submetida à legislação consumerista, serão preservados os direitos obrigatórios assegurados ao consumidor.
23.2. Nenhuma disposição deste contrato será interpretada com a finalidade de afastar norma cogente aplicável à relação.

CLÁUSULA 24ª — DO FORO
24.1. Fica eleito o foro da Comarca do Rio de Janeiro/RJ, por possuir pertinência com o domicílio da LOCADORA, para dirimir controvérsias decorrentes deste contrato.
24.2. Fica ressalvado o foro legalmente assegurado ao consumidor ou outra competência obrigatória quando aplicável.

CLÁUSULA 25ª — DAS DISPOSIÇÕES FINAIS
25.1. O Quadro-Resumo, tabela de equipamentos, comprovantes de entrega, termos de substituição, aditivos e outros documentos expressamente vinculados integram este contrato.
25.2. A eventual nulidade ou inexigibilidade de uma disposição específica não invalidará automaticamente as demais cláusulas.
25.3. Cada contrato permanecerá vinculado à versão do modelo vigente na data de sua celebração, não sendo alterações futuras aplicadas retroativamente.
25.4. O presente instrumento entra em vigor na data registrada pelas partes.`;

const DEFAULT_MODEL_DEFS = [
  {tipo:'contrato_locacao',nome:'Contrato de Locação de Equipamentos',versao:'1.0',corpo:DEFAULT_CONTRACT_BODY},
  {tipo:'comprovante_entrega',nome:'Comprovante de Entrega de Equipamento',versao:'1.0',corpo:'A LOCATÁRIA declara receber os equipamentos acima identificados no estado registrado pela Safety Equipamentos, comprometendo-se a utilizá-los adequadamente, conservá-los e devolvê-los ao término do período acordado, ressalvado o desgaste natural decorrente do uso regular. Alterações de endereço, substituições e devoluções deverão ser comunicadas e registradas junto à LOCADORA.'},
  {tipo:'entrada_assistencia',nome:'Comprovante de Entrada de Equipamento',versao:'1.0',corpo:'O equipamento acima identificado foi recebido pela Safety Equipamentos para avaliação técnica. O defeito informado corresponde ao relato inicial do cliente e não constitui diagnóstico definitivo. A condição final, orçamento e serviços dependerão da análise técnica. Os acessórios recebidos estão discriminados neste documento.'},
  {tipo:'termo_emprestimo',nome:'Termo de Empréstimo de Equipamento',versao:'1.0',corpo:'O cliente declara receber temporariamente o equipamento da Safety Equipamentos acima identificado enquanto seu equipamento permanece em assistência. O bem deverá ser utilizado adequadamente e devolvido quando solicitado ou quando concluído o atendimento relacionado.'},
  {tipo:'termo_substituicao',nome:'Termo de Substituição de Equipamento',versao:'1.0',corpo:'As partes registram a substituição do equipamento anteriormente vinculado à locação pelo equipamento substituto acima identificado. A substituição não altera as demais condições da locação, salvo quando houver registro expresso em sentido diverso.'},
  {tipo:'aditivo_responsavel',nome:'Termo de Alteração de Responsável',versao:'1.0',corpo:'Fica registrada a alteração do responsável indicado para a locação, mantendo-se inalterada a parte contratante e as demais condições do contrato principal. O histórico do responsável anterior permanece preservado no sistema.'},
  {tipo:'orcamento',nome:'Orçamento de Assistência Técnica',versao:'1.0',corpo:'O orçamento apresentado decorre da avaliação técnica registrada e poderá ser revisto caso sejam identificadas condições ocultas ou necessidades adicionais, mediante comunicação ao cliente antes da execução adicional.'},
  {tipo:'relatorio_manutencao',nome:'Relatório de Manutenção',versao:'1.0',corpo:'O presente relatório registra os serviços executados e o resultado dos testes técnicos realizados no equipamento identificado.'},
  {tipo:'recibo',nome:'Recibo de Serviço',versao:'1.0',corpo:'O presente recibo comprova o recebimento do valor indicado referente ao atendimento técnico identificado.'}
];

async function ensureDefaultModels(){
  for(const def of DEFAULT_MODEL_DEFS){if((data.modelosDocumentos||[]).some(m=>m.tipo===def.tipo))continue;const id=`${def.tipo}_v1_0`,obj={...def,status:'Ativo',vigenciaInicio:todayISO(),revisadoPor:'Modelo-base interno — sujeito à revisão jurídica profissional',motivo:'Modelo inicial V1 Definitiva',ativo:true,criadoEm:nowISO(),criadoPor:currentUser.uid};await db.collection(COLS.modelosDocumentos).doc(id).set(obj);data.modelosDocumentos.push({id,...obj})}
}
function getActiveModel(tipo){return (data.modelosDocumentos||[]).filter(m=>m.tipo===tipo&&m.status==='Ativo'&&!isArchived(m)).sort((a,b)=>(b.ativadoEm||b.criadoEm||'').localeCompare(a.ativadoEm||a.criadoEm||''))[0]||DEFAULT_MODEL_DEFS.find(x=>x.tipo===tipo)}
function renderBodyText(body,ctx={}){let s=esc(body||'');Object.entries(ctx).forEach(([k,v])=>{s=s.split(`{{${k}}}`).join(esc(v??''))});return s.split(/\n{2,}/).map(p=>`<p>${p.replace(/\n/g,'<br>')}</p>`).join('')}
function viewModelosDocumentos(){
  if(!isAdmin())return empty('Acesso restrito.');const rows=(data.modelosDocumentos||[]).filter(x=>x.excluido!==true).sort((a,b)=>(a.tipo||'').localeCompare(b.tipo||'')||(b.criadoEm||'').localeCompare(a.criadoEm||''));
  return `<div class="card"><div class="row"><div><h2>Modelos de Documentos</h2><p class="hint">O conteúdo jurídico é versionado. Modelos já utilizados não são alterados retroativamente; crie uma nova versão para qualquer revisão, inclusive por advogado.</p></div><div class="inline-actions"><button class="btn ghost" onclick="go('configuracoes')">← Configurações</button><button class="btn" onclick="novoModeloDocumento()">+ Novo modelo</button></div></div><div class="notice blue"><b>Regra de integridade:</b> versões Ativas/Arquivadas são somente leitura. Para alterar, use “Criar nova versão”.</div>${rows.length?`<table><thead><tr><th>Documento</th><th>Versão</th><th>Status</th><th>Vigência</th><th>Revisão</th><th>Ações</th></tr></thead><tbody>${rows.map(m=>`<tr><td><b>${esc(m.nome||modelTypeLabel(m.tipo))}</b><br><span class="muted">${esc(m.tipo)}</span></td><td>${esc(m.versao||'—')}</td><td>${tag(m.status||'Rascunho',m.status==='Ativo'?'ok':m.status==='Rascunho'?'warn':'info')}</td><td>${dateBR(m.vigenciaInicio)}</td><td>${esc(m.revisadoPor||'—')}<br><span class="muted">${esc(m.motivo||'')}</span></td><td><div class="inline-actions"><button class="btn small ghost" onclick="previewModelo('${m.id}')">Prévia</button>${m.status==='Rascunho'?`<button class="btn small ghost" onclick="editarModeloDocumento('${m.id}')">Editar</button><button class="btn small" onclick="ativarModeloDocumento('${m.id}')">Ativar</button>`:`<button class="btn small ghost" onclick="novaVersaoModelo('${m.id}')">Criar nova versão</button>`}</div></td></tr>`).join('')}</tbody></table>`:empty('Nenhum modelo cadastrado.')}</div>`
}
function novoModeloDocumento(){abrirModal('Novo modelo de documento',`<div class="grid2"><div><label>Tipo *</label><select id="mdTipo">${DEFAULT_MODEL_DEFS.map(d=>`<option value="${d.tipo}">${esc(d.nome)}</option>`).join('')}</select></div><div><label>Versão *</label><input id="mdVersao" value="1.0"></div><div><label>Nome *</label><input id="mdNome"></div><div><label>Data de vigência</label><input id="mdVig" type="date" value="${todayISO()}"></div><div><label>Revisado por</label><input id="mdRev" placeholder="Ex.: Adv. Nome — OAB/UF nº..."></div><div><label>Motivo da revisão</label><input id="mdMotivo"></div></div><label>Corpo / cláusulas *</label><textarea id="mdCorpo" class="contract-editor" placeholder="Cole ou escreva o corpo do documento"></textarea><p class="hint">Os dados de cliente, equipamentos, valores, endereço e assinaturas são montados pelo sistema fora deste corpo e permanecem protegidos.</p>`,`<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarModeloDocumento('')">Salvar rascunho</button>`)}
function editarModeloDocumento(id){const m=(data.modelosDocumentos||[]).find(x=>x.id===id);if(!m||m.status!=='Rascunho')return alert('Somente rascunhos podem ser editados. Crie uma nova versão.');abrirModal('Editar modelo',`<div class="grid2"><div><label>Tipo</label><input value="${esc(modelTypeLabel(m.tipo))}" disabled><input id="mdTipo" type="hidden" value="${esc(m.tipo)}"></div><div><label>Versão *</label><input id="mdVersao" value="${esc(m.versao||'')}"></div><div><label>Nome *</label><input id="mdNome" value="${esc(m.nome||'')}"></div><div><label>Data de vigência</label><input id="mdVig" type="date" value="${esc(m.vigenciaInicio||todayISO())}"></div><div><label>Revisado por</label><input id="mdRev" value="${esc(m.revisadoPor||'')}"></div><div><label>Motivo da revisão</label><input id="mdMotivo" value="${esc(m.motivo||'')}"></div></div><label>Corpo / cláusulas *</label><textarea id="mdCorpo" class="contract-editor">${esc(m.corpo||'')}</textarea>`,`<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarModeloDocumento('${id}')">Salvar rascunho</button>`)}
async function salvarModeloDocumento(id){if(!isAdmin())return;const tipo=$('mdTipo').value,versao=$('mdVersao').value.trim(),nome=$('mdNome').value.trim()||modelTypeLabel(tipo),corpo=$('mdCorpo').value.trim();if(!tipo||!versao||!corpo)return alert('Informe tipo, versão e corpo do documento.');const dup=(data.modelosDocumentos||[]).find(x=>x.id!==id&&x.tipo===tipo&&normalize(x.versao)===normalize(versao));if(dup)return alert('Já existe esta versão para o tipo selecionado.');const obj={tipo,versao,nome,corpo,status:'Rascunho',vigenciaInicio:$('mdVig').value||todayISO(),revisadoPor:$('mdRev').value.trim(),motivo:$('mdMotivo').value.trim(),ativo:true};if(id)await setDoc(COLS.modelosDocumentos,id,obj);else await addDoc(COLS.modelosDocumentos,obj);await audit(id?'editar_modelo':'criar_modelo','Modelos de Documentos',id||`${tipo}-${versao}`,`${nome} v${versao} salvo como rascunho.`);fecharModal();await refresh('Modelo salvo como rascunho.')}
async function ativarModeloDocumento(id){if(!isAdmin())return;const m=(data.modelosDocumentos||[]).find(x=>x.id===id);if(!m||m.status!=='Rascunho')return;if(!confirm(`Ativar ${m.nome} v${m.versao}? A versão atualmente ativa será arquivada.`))return;requireOnline();const batch=db.batch();(data.modelosDocumentos||[]).filter(x=>x.tipo===m.tipo&&x.status==='Ativo'&&x.id!==id).forEach(x=>batch.set(db.collection(COLS.modelosDocumentos).doc(x.id),{status:'Arquivado',arquivadoEm:nowISO(),arquivadoPor:currentUser.uid},{merge:true}));batch.set(db.collection(COLS.modelosDocumentos).doc(id),{status:'Ativo',ativadoEm:nowISO(),ativadoPor:currentUser.uid},{merge:true});await batch.commit();await audit('ativar_modelo','Modelos de Documentos',id,`${m.nome} v${m.versao} ativado.`);await refresh('Nova versão ativada.')}
async function novaVersaoModelo(id){const m=(data.modelosDocumentos||[]).find(x=>x.id===id);if(!m)return;const v=prompt('Número da nova versão:',incrementVersion(m.versao||'1.0'));if(!v)return;const nid=await addDoc(COLS.modelosDocumentos,{tipo:m.tipo,nome:m.nome,versao:v,corpo:m.corpo,status:'Rascunho',vigenciaInicio:todayISO(),revisadoPor:'',motivo:`Nova versão baseada na v${m.versao}`,ativo:true,baseadoEm:id});await audit('nova_versao','Modelos de Documentos',nid,`${m.nome} v${v} criada a partir da v${m.versao}.`);await refresh(null,false);editarModeloDocumento(nid)}
function incrementVersion(v){const p=String(v).split('.').map(Number);return `${Number.isFinite(p[0])?p[0]:1}.${(Number.isFinite(p[1])?p[1]:0)+1}`}
function previewModelo(id){const m=(data.modelosDocumentos||[]).find(x=>x.id===id);if(!m)return;const html=`<div class="pdf-doc">${pdfHead()}<h1 class="pdf-title">${esc((m.nome||modelTypeLabel(m.tipo)).toUpperCase())}</h1><div class="pdf-meta"><b>MODELO DE PRÉ-VISUALIZAÇÃO</b><br>Cliente: CLIENTE EXEMPLO · CPF/CNPJ: 00.000.000/0001-00<br>Equipamento: Autoclave · Modelo X · Fabricante Y · Série TESTE-001 · 220V</div><div class="pdf-section contract-body">${renderBodyText(m.corpo,{})}</div>${pdfFooter()}</div>`;abrirModal(`Prévia · ${m.nome} v${m.versao}`,`<div class="model-preview">${html}</div>`,`<button class="btn ghost" onclick="fecharModal()">Fechar</button>`)}

function viewUsuarios(){if(!isAdmin())return empty('Acesso restrito.');const rows=allRecords('usuarios').sort((a,b)=>(a.nome||'').localeCompare(b.nome||''));return `<div class="card"><div class="row"><div><h2>Usuários</h2><p class="hint">Função identifica o colaborador; perfil define as permissões do sistema.</p></div><button class="btn" onclick="novoUsuario()">+ Novo usuário</button></div>${rows.length?`<table><thead><tr><th>Nome</th><th>Matrícula</th><th>Função</th><th>Perfil</th><th>Ativo</th><th>Ações</th></tr></thead><tbody>${rows.map(u=>`<tr><td><b>${esc(u.nome)}</b><br><span class="muted">${esc(u.email||'')}</span></td><td>${esc(u.matricula||'—')}</td><td>${esc(u.funcao||'—')}</td><td>${tag((u.perfil||(u.admin?'administrativo':'tecnico'))==='administrativo'?'Administrativo':'Técnico','info')}</td><td>${u.ativo!==false?tag('Sim','ok'):tag('Não','danger')}</td><td><div class="inline-actions"><button class="btn small ghost" onclick="editarUsuarioPerfil('${u.id}')">Editar</button>${u.id!==currentUser.uid?`<button class="btn small ghost" onclick="toggleUsuario('${u.id}',${u.ativo!==false?'false':'true'})">${u.ativo!==false?'Desativar':'Ativar'}</button>`:''}</div></td></tr>`).join('')}</tbody></table>`:empty('Nenhum usuário cadastrado.')}</div>`}
function novoUsuario(){if(!isAdmin())return;abrirModal('Novo usuário',`<div class="grid2"><div><label>Nome *</label><input id="nuNome"></div><div><label>E-mail *</label><input id="nuEmail" type="email"></div><div><label>Matrícula *</label><input id="nuMatricula"></div><div><label>Função *</label><input id="nuFuncao" placeholder="Ex.: Técnico de Manutenção"></div><div><label>Perfil de acesso *</label><select id="nuPerfil"><option value="tecnico">Técnico / Operacional</option><option value="administrativo">Administrativo</option></select></div><div><label>Senha provisória *</label><input id="nuSenha" type="password" minlength="6"></div></div><p class="hint">O usuário fica vinculado ao próprio cadastro funcional. Função e matrícula também serão usadas nos documentos assinados.</p>`,`<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarNovoUsuario()">Criar usuário</button>`)}
async function salvarNovoUsuario(){const nome=$('nuNome').value.trim(),email=$('nuEmail').value.trim(),senha=$('nuSenha').value,matricula=$('nuMatricula').value.trim(),funcao=$('nuFuncao').value.trim(),perfil=$('nuPerfil').value;if(!nome||!email||!matricula||!funcao||senha.length<6)return alert('Preencha nome, e-mail, matrícula, função e use senha com no mínimo 6 caracteres.');try{requireOnline();const secondary=firebase.initializeApp(CFG.firebase,'ce-secondary-'+Date.now()),cred=await secondary.auth().createUserWithEmailAndPassword(email,senha),uid=cred.user.uid;await db.collection(COLS.usuarios).doc(uid).set({nome,email,matricula,funcao,perfil,ativo:true,admin:perfil==='administrativo',criadoEm:nowISO(),criadoPor:currentUser.uid});await secondary.auth().signOut();await secondary.delete();await audit('criar','Usuários',uid,`Usuário ${nome} criado com perfil ${perfil}.`);fecharModal();await refresh('Usuário criado.')}catch(e){alert('Não foi possível criar o usuário: '+e.message)}}
function editarUsuarioPerfil(uid){const u=(data.usuarios||[]).find(x=>x.id===uid);if(!u)return;abrirModal('Editar usuário',`<div class="grid2"><div><label>Nome *</label><input id="euNome" value="${esc(u.nome||'')}"></div><div><label>E-mail</label><input value="${esc(u.email||'')}" disabled></div><div><label>Matrícula *</label><input id="euMatricula" value="${esc(u.matricula||'')}"></div><div><label>Função *</label><input id="euFuncao" value="${esc(u.funcao||'')}"></div><div><label>Perfil de acesso *</label><select id="euPerfil"><option value="tecnico" ${(u.perfil||(u.admin?'administrativo':'tecnico'))==='tecnico'?'selected':''}>Técnico / Operacional</option><option value="administrativo" ${(u.perfil||(u.admin?'administrativo':'tecnico'))==='administrativo'?'selected':''}>Administrativo</option></select></div><div><label>Ativo</label><select id="euAtivo"><option value="true" ${u.ativo!==false?'selected':''}>Sim</option><option value="false" ${u.ativo===false?'selected':''}>Não</option></select></div></div>`,`<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarUsuarioPerfil('${uid}')">Salvar</button>`)}
async function salvarUsuarioPerfil(uid){const nome=$('euNome').value.trim(),matricula=$('euMatricula').value.trim(),funcao=$('euFuncao').value.trim(),perfil=$('euPerfil').value;if(!nome||!matricula||!funcao)return alert('Nome, matrícula e função são obrigatórios.');if(uid===currentUser.uid&&$('euAtivo').value==='false')return alert('Você não pode desativar o próprio usuário durante a sessão.');await setDoc(COLS.usuarios,uid,{nome,matricula,funcao,perfil,admin:perfil==='administrativo',ativo:$('euAtivo').value==='true'});await audit('editar','Usuários',uid,`Cadastro funcional/permissão de ${nome} atualizado.`);fecharModal();await refresh('Usuário atualizado.')}

function configDoc(){return data.configuracoes.find(x=>x.id==='geral')||{id:'geral',baseStatus:'implantacao',diasAlertaContrato:30,diasAlertaPreventiva:15}}
function publicConfigDoc(){return data.configuracoes.find(x=>x.id==='publico')||{id:'publico',requestNotificationWebhook:CFG.requestNotificationWebhook||''}}
function viewConfiguracoes(){if(!isAdmin())return empty('Acesso restrito.');const cfg=configDoc(),pub=publicConfigDoc(),cats=active('categorias'),fabs=active('fabricantes'),arch=HOMOLOGATION_COLLECTIONS.reduce((s,k)=>s+(data[k]||[]).filter(x=>x.arquivado&&x.origem==='homologacao_v1').length,0);return `<div class="card"><h2>Configurações</h2><div class="grid2"><div><h3>Implantação da base</h3><label>Status da base</label><select id="cfgBase"><option value="implantacao" ${cfg.baseStatus==='implantacao'?'selected':''}>Em implantação</option><option value="operacao" ${cfg.baseStatus==='operacao'?'selected':''}>Base operacional</option></select><div class="grid2"><div><label>Alerta de contrato (dias)</label><input id="cfgContrato" type="number" value="${cfg.diasAlertaContrato||30}"></div><div><label>Alerta preventiva (dias)</label><input id="cfgPrev" type="number" value="${cfg.diasAlertaPreventiva||15}"></div></div><button class="btn" onclick="salvarConfigGeral()">Salvar configurações</button></div><div><h3>Notificação de nova solicitação</h3><p class="hint">Informe um webhook HTTPS (ex.: Apps Script ou Power Automate). O formulário público enviará um aviso após gravar a solicitação.</p><label>Webhook externo</label><input id="cfgWebhook" value="${esc(pub.requestNotificationWebhook||'')}" placeholder="https://..."><button class="btn" onclick="salvarConfigPublica()">Salvar webhook</button>${pub.requestNotificationWebhook?'<p class="tag ok">Webhook configurado</p>':'<p class="tag warn">Alerta externo ainda não configurado</p>'}</div></div></div>
  <div class="card"><div class="row"><div><h2>Modelos e documentos</h2><p class="hint">Contratos e termos versionados, com corpo editável e estrutura dinâmica protegida.</p></div><button class="btn" onclick="go('modelos')">Abrir Modelos de Documentos</button></div></div>
  <div class="card"><h2>Dados de homologação</h2><p class="hint">Os registros dos testes da V1 podem ser arquivados sem exclusão. Arquivados não aparecem no Dashboard nem nas listas operacionais.</p><div class="metric-row"><div class="metric"><span>Registros de homologação arquivados</span><strong>${arch}</strong></div></div><div class="inline-actions"><button class="btn danger" onclick="archivarDadosHomologacao()">Arquivar dados atuais de teste</button><button class="btn ghost" onclick="reativarDadosHomologacao()">Reativar homologação</button></div></div>
  <div class="card"><div class="row"><div><h2>Exportação administrativa</h2><p class="hint">Somente leitura; não altera a base.</p></div></div><div class="inline-actions"><button class="btn ghost" onclick="exportarCSV('clientes')">Clientes CSV</button><button class="btn ghost" onclick="exportarCSV('equipamentos')">Equipamentos CSV</button><button class="btn ghost" onclick="exportarCSV('locacoes')">Locações CSV</button><button class="btn ghost" onclick="exportarCSV('assistencias')">Assistências CSV</button><button class="btn ghost" onclick="exportarCSV('cobrancas')">Cobranças CSV</button></div></div>
  <div class="card"><div class="grid2"><div><h3>Fabricantes / marcas</h3><div class="inline-actions"><input id="fabNome" placeholder="Novo fabricante"><button class="btn small" onclick="addFabricante()">Adicionar</button></div><div class="chip-list">${fabs.map(f=>`<span class="chip">${esc(f.nome)}</span>`).join('')||'<span class="hint">Nenhum fabricante.</span>'}</div></div><div><h3>Segurança</h3><p class="hint">Antes da produção: restringir a chave Web/API aos domínios autorizados e publicar as regras Firestore fornecidas no pacote.</p><p>${connectionBadgeHtml()}</p></div></div></div>
  <div class="card"><div class="row"><div><h2>Categorias e modelos técnicos</h2><p class="hint">Parâmetros, checklists de saída/retorno e periodicidade preventiva por categoria.</p></div><button class="btn" onclick="editarCategoria()">+ Nova categoria</button></div>${cats.length?`<table><thead><tr><th>Categoria</th><th>Itens de teste</th><th>Checklist saída</th><th>Checklist retorno</th><th>Ações</th></tr></thead><tbody>${cats.map(c=>`<tr><td><b>${esc(c.nome)}</b></td><td>${(c.itensTeste||[]).length}</td><td>${(c.checklistSaida||[]).length}</td><td>${(c.checklistRetorno||[]).length}</td><td><button class="btn small ghost" onclick="editarCategoria('${c.id}')">Editar</button></td></tr>`).join('')}</tbody></table>`:empty('Cadastre as categorias utilizadas pela Safety.')}</div>`}
async function salvarConfigGeral(){await db.collection(COLS.configuracoes).doc('geral').set({baseStatus:$('cfgBase').value,diasAlertaContrato:Number($('cfgContrato').value||30),diasAlertaPreventiva:Number($('cfgPrev').value||15),alteradoEm:nowISO(),alteradoPor:currentUser.uid},{merge:true});await audit('editar','Configurações','geral','Configurações gerais atualizadas.');await refresh('Configurações salvas.')}
async function salvarConfigPublica(){const url=$('cfgWebhook').value.trim();if(url&&!/^https:\/\//i.test(url))return alert('Informe um endereço HTTPS válido.');await db.collection(COLS.configuracoes).doc('publico').set({requestNotificationWebhook:url,alteradoEm:nowISO(),alteradoPor:currentUser.uid},{merge:true});await audit('editar','Configurações','publico','Webhook de notificações atualizado.');await refresh('Configuração de notificação salva.')}

async function initPublicRequest(){
  $('login').classList.add('hidden');$('appShell').classList.add('hidden');$('publicRequest').classList.remove('hidden');
  let cats=[];try{const s=await db.collection(COLS.categorias).where('ativo','==',true).get();cats=s.docs.map(d=>({id:d.id,...d.data()}))}catch(e){console.warn(e)}
  try{const c=await db.collection(COLS.configuracoes).doc('publico').get();publicRuntimeConfig=c.exists?c.data():{}}catch(e){publicRuntimeConfig={}}
  $('publicRequest').innerHTML=publicRequestHtml(cats);
}
async function enviarSolicitacaoPublica(ev){
  ev.preventDefault();if(!navigator.onLine)return alert('Sem conexão com a internet. Reconecte-se antes de enviar a solicitação.');const btn=$('prSubmit');btn.disabled=true;btn.textContent='Enviando...';
  try{const protocolo=`SOL-${new Date().getFullYear()}-${Date.now().toString().slice(-8)}`,obj={protocolo,status:'Nova',tipoPessoa:$('prTipo').value,nomeRazao:$('prNome').value.trim(),cpfCnpj:$('prCpf').value.trim(),responsavel:$('prResp').value.trim(),cpfResponsavel:$('prCpfResp').value.trim(),segmento:$('prSegmento').value.trim(),categoriaId:$('prCategoria').value,equipamentoDescricao:$('prEquipDesc').value.trim(),quantidade:Number($('prQtd').value||1),tensao:$('prTensao').value.trim(),inicioPretendido:$('prInicio').value,periodoPretendido:$('prPeriodo').value.trim(),observacoes:$('prObs').value.trim(),enderecoInstalacao:readAddress('prInst'),enderecoResidencial:readAddress('prRes'),telefone:$('prTel').value.trim(),telefoneReferencia:$('prTelRef').value.trim(),email:$('prEmail').value.trim(),origem:$('prOrigem').value.trim(),aceiteEm:nowISO(),criadoEm:nowISO(),criadoPor:'publico',ativo:true};const ref=db.collection(COLS.solicitacoes).doc();await ref.set(obj);const hook=publicRuntimeConfig.requestNotificationWebhook||CFG.requestNotificationWebhook;if(hook){fetch(hook,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:ref.id,protocolo,nome:obj.nomeRazao,equipamento:obj.equipamentoDescricao||obj.categoriaId,email:obj.email,telefone:obj.telefone,recebidaEm:obj.criadoEm})}).catch(()=>{})}$('publicRequest').innerHTML=`<div class="public-shell"><div class="public-body success-box"><div class="big">✓</div><h2>Solicitação enviada</h2><p>A equipe da Safety Equipamentos analisará os dados e entrará em contato.</p><p class="hint">Protocolo: <b>${esc(protocolo)}</b></p><a class="btn" href="./index.html" style="display:inline-grid;place-items:center;text-decoration:none;margin-top:16px">Concluir</a></div></div>`}catch(e){alert('Não foi possível enviar a solicitação: '+e.message);btn.disabled=false;btn.textContent='Enviar solicitação'}
}

function viewSolicitacoes(){if(!isAdmin())return empty('Acesso restrito.');const rows=active('solicitacoes').sort((a,b)=>(b.criadoEm||'').localeCompare(a.criadoEm||''));return `<div class="card"><div class="row"><div><h2>Solicitações de locação</h2><p class="hint">Pré-cadastros do formulário público. A conversão preserva o histórico e evita redigitação.</p></div><a class="btn ghost" href="?solicitar=1" target="_blank" style="text-decoration:none">Abrir formulário público</a></div><input class="search" placeholder="Pesquisar protocolo, interessado, CPF/CNPJ, telefone..." oninput="filterTable('solTable',this.value)">${rows.length?`<table id="solTable"><thead><tr><th>Protocolo/Data</th><th>Interessado</th><th>Equipamento</th><th>Contato</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(s=>`<tr data-search="${esc([s.protocolo,s.nomeRazao,s.cpfCnpj,s.telefone,s.email,s.equipamentoDescricao].join(' '))}"><td><b>${esc(s.protocolo||s.id)}</b><br><span class="muted">${dateTimeBR(s.criadoEm)}</span></td><td><b>${esc(s.nomeRazao)}</b><br><span class="muted">${esc(s.cpfCnpj||'')}</span></td><td>${esc(s.equipamentoDescricao||categoryName(s.categoriaId))}</td><td>${esc(s.telefone||'')}<br>${esc(s.email||'')}</td><td>${tag(s.status,statusType(s.status))}</td><td><div class="inline-actions"><button class="btn small ghost" onclick="detalharSolicitacao('${s.id}')">Abrir</button>${s.status!=='Convertida'?`<button class="btn small" onclick="converterSolicitacao('${s.id}')">Converter</button>`:''}</div></td></tr>`).join('')}</tbody></table>`:empty('Nenhuma solicitação recebida.')}</div>`}
async function converterSolicitacao(id){const s=find('solicitacoes',id);if(!s)return;const existente=data.clientes.find(c=>!isArchived(c)&&normalizeDoc(c.cpfCnpj)===normalizeDoc(s.cpfCnpj)&&s.cpfCnpj);if(existente){if(!confirm(`Já existe o cliente ${existente.nomeRazao}. Vincular esta solicitação a ele?`))return;await setDoc(COLS.solicitacoes,id,{status:'Convertida',clienteId:existente.id,convertidaEm:nowISO()});await audit('converter','Solicitações',id,`Solicitação vinculada ao cliente ${existente.nomeRazao}.`);await refresh('Solicitação vinculada ao cliente existente.');return}const obj={tipoPessoa:s.tipoPessoa||'PF',cadastroNivel:'completo',nomeRazao:s.nomeRazao,cpfCnpj:s.cpfCnpj,responsavel:s.responsavel||'',cpfResponsavel:s.cpfResponsavel||'',segmento:s.segmento||'',telefone:s.telefone||'',telefoneReferencia:s.telefoneReferencia||'',email:s.email||'',origem:s.origem||'',enderecoCadastral:s.enderecoResidencial||{},enderecosInstalacao:s.enderecoInstalacao?[s.enderecoInstalacao]:[],ativo:true,historicoCadastral:[],origemSolicitacaoId:id};const cid=await addDoc(COLS.clientes,obj);await setDoc(COLS.solicitacoes,id,{status:'Convertida',clienteId:cid,convertidaEm:nowISO()});await audit('converter','Solicitações',id,`Solicitação ${s.protocolo||id} convertida em cliente ${obj.nomeRazao}.`);await refresh('Cliente criado a partir do pré-cadastro.');go('clientes')}

function viewClientes(){const rows=active('clientes').sort((a,b)=>(a.nomeRazao||'').localeCompare(b.nomeRazao||''));return `<div class="card"><div class="row"><div><h2>Clientes</h2><p class="hint">Cadastros completos para locação e cadastros rápidos para assistência técnica.</p></div><div class="inline-actions">${isAdmin()?`<button class="btn ghost" onclick="exportarCSV('clientes')">Exportar CSV</button>`:''}<button class="btn" onclick="editarCliente()">+ Novo cliente</button></div></div><input class="search" id="cliSearch" placeholder="Pesquisar cliente, CPF/CNPJ, telefone..." oninput="filterTable('cliTable',this.value)">${rows.length?`<table id="cliTable"><thead><tr><th>Cliente</th><th>Documento</th><th>Responsável</th><th>Contato</th><th>Cadastro</th><th>Ações</th></tr></thead><tbody>${rows.map(c=>`<tr data-search="${esc([c.nomeRazao,c.cpfCnpj,c.responsavel,c.telefone,c.email,c.segmento].join(' '))}"><td><b>${esc(c.nomeRazao)}</b><br><span class="muted">${esc(c.tipoPessoa||'')}</span></td><td>${esc(c.cpfCnpj||'—')}</td><td>${esc(c.responsavel||'—')}</td><td>${esc(c.telefone||'—')}<br><span class="muted">${esc(c.email||'')}</span></td><td>${tag(c.cadastroNivel==='rapido'?'Rápido':'Completo',c.cadastroNivel==='rapido'?'warn':'ok')}</td><td><div class="inline-actions"><button class="btn small ghost" onclick="detalharCliente('${c.id}')">Abrir</button><button class="btn small ghost" onclick="editarCliente('${c.id}')">Editar</button>${c.cadastroNivel==='rapido'?`<button class="btn small" onclick="editarCliente('${c.id}')">Completar cadastro</button>`:''}</div></td></tr>`).join('')}</tbody></table>`:empty('Nenhum cliente cadastrado.')}</div>`}
function clienteForm(c={}){return `<div class="grid2"><div><label>Tipo *</label><select id="cTipo"><option value="PF" ${c.tipoPessoa!=='PJ'?'selected':''}>PF</option><option value="PJ" ${c.tipoPessoa==='PJ'?'selected':''}>PJ</option></select></div><div><label>Nível do cadastro</label><select id="cNivel"><option value="completo" ${c.cadastroNivel!=='rapido'?'selected':''}>Completo</option><option value="rapido" ${c.cadastroNivel==='rapido'?'selected':''}>Rápido / avulso</option></select></div><div><label>Nome / Razão Social *</label><input id="cNome" value="${esc(c.nomeRazao||'')}"></div><div><label>CPF / CNPJ ${c.cadastroNivel==='rapido'?'':'*'}</label><input id="cCpf" value="${esc(c.cpfCnpj||'')}"></div><div><label>Responsável</label><input id="cResp" value="${esc(c.responsavel||'')}"></div><div><label>CPF do responsável</label><input id="cCpfResp" value="${esc(c.cpfResponsavel||'')}"></div><div><label>Segmento</label><input id="cSegmento" value="${esc(c.segmento||'')}"></div><div><label>Telefone / WhatsApp *</label><input id="cTel" value="${esc(c.telefone||'')}"></div><div><label>Telefone de referência</label><input id="cTelRef" value="${esc(c.telefoneReferencia||'')}"></div><div><label>E-mail</label><input id="cEmail" type="email" value="${esc(c.email||'')}"></div><div><label>Origem do contato</label><input id="cOrigem" value="${esc(c.origem||'')}"></div></div><div class="section-title">Endereço cadastral / residencial</div>${addressForm('cEnd',c.enderecoCadastral||{})}<div class="section-title">Endereço de instalação principal</div>${addressForm('cInst',(c.enderecosInstalacao||[])[0]||{})}`}
async function salvarCliente(id){const nome=$('cNome').value.trim(),cpf=$('cCpf').value.trim(),tel=$('cTel').value.trim(),nivel=$('cNivel').value;if(!nome||!tel)return alert('Informe Nome/Razão Social e telefone/WhatsApp.');if(nivel==='completo'&&!cpf)return alert('CPF/CNPJ é obrigatório no cadastro completo.');if(cpf){const dup=data.clientes.find(x=>x.id!==id&&!isArchived(x)&&normalizeDoc(x.cpfCnpj)===normalizeDoc(cpf));if(dup)return alert(`Já existe um cliente com este CPF/CNPJ: ${dup.nomeRazao}.`)}if(nivel==='rapido'&&tel){const same=data.clientes.find(x=>x.id!==id&&!isArchived(x)&&normalizedPhone(x.telefone)===normalizedPhone(tel));if(same&&!confirm(`Já existe um cliente com este telefone: ${same.nomeRazao}. Deseja salvar mesmo assim?`))return}const before=id?clone(find('clientes',id)):null,obj={tipoPessoa:$('cTipo').value,cadastroNivel:nivel,nomeRazao:nome,cpfCnpj:cpf,responsavel:$('cResp').value.trim(),cpfResponsavel:$('cCpfResp').value.trim(),segmento:$('cSegmento').value.trim(),telefone:tel,telefoneReferencia:$('cTelRef').value.trim(),email:$('cEmail').value.trim(),origem:$('cOrigem').value.trim(),enderecoCadastral:modalAddress('cEnd'),enderecosInstalacao:[modalAddress('cInst')],ativo:true,arquivado:false};if(id){const hist=[...(before.historicoCadastral||[])];if(JSON.stringify(before.enderecoCadastral)!==JSON.stringify(obj.enderecoCadastral)||before.responsavel!==obj.responsavel||before.cadastroNivel!==obj.cadastroNivel)hist.push({em:nowISO(),responsavelAnterior:before.responsavel||'',enderecoAnterior:before.enderecoCadastral||{},cadastroNivelAnterior:before.cadastroNivel||'completo',alteradoPor:currentUser.uid});obj.historicoCadastral=hist;await setDoc(COLS.clientes,id,obj);await audit('editar','Clientes',id,`Cliente ${nome} atualizado.`,before,obj)}else{const nid=await addDoc(COLS.clientes,{...obj,historicoCadastral:[]});await audit('criar','Clientes',nid,`Cliente ${nome} cadastrado.`,null,obj)}fecharModal();await refresh('Cliente salvo.')}
function detalharCliente(id){const c=find('clientes',id),ass=active('assistencias').filter(x=>x.clienteId===id);if(!c)return;const financial=isAdmin()?`<div class="metric-row"><div class="metric"><span>Locações</span><strong>${active('locacoes').filter(x=>x.clienteId===id).length}</strong></div><div class="metric"><span>Cobranças</span><strong>${active('cobrancas').filter(x=>x.clienteId===id).length}</strong></div></div>`:'';abrirModal(c.nomeRazao,`<div class="grid2"><div><div class="section-title">Cadastro</div><p>${esc(c.tipoPessoa)} · ${esc(c.cpfCnpj||'Sem documento')}</p><p>Responsável: ${esc(c.responsavel||'—')}</p><p>${esc(c.telefone||'—')} · ${esc(c.email||'—')}</p><p>${esc(formatAddress(c.enderecoCadastral))}</p></div><div>${financial}<div class="metric"><span>Assistências</span><strong>${ass.length}</strong></div></div></div><div class="section-title">Equipamentos atendidos / histórico</div>${ass.length?ass.sort((a,b)=>(b.entrada||'').localeCompare(a.entrada||'')).slice(0,12).map(a=>`<div class="timeline-item"><strong>${esc(a.protocolo||a.id)} · ${dateBR(a.entrada)} · Série ${esc(a.serial)}</strong><p>${esc(a.defeitoRelatado||a.diagnostico||'')}</p></div>`).join(''):empty('Sem assistências registradas.')}<div class="section-title">Histórico cadastral</div>${(c.historicoCadastral||[]).length?c.historicoCadastral.map(h=>`<div class="timeline-item"><strong>${dateTimeBR(h.em)}</strong><p>Responsável anterior: ${esc(h.responsavelAnterior||'—')} · ${esc(formatAddress(h.enderecoAnterior))}</p></div>`).join(''):empty('Sem alterações registradas.')}`,`<button class="btn ghost" onclick="fecharModal()">Fechar</button><button class="btn" onclick="fecharModal();editarCliente('${id}')">Editar</button>`)}

function viewEquipamentos(){const rows=active('equipamentos').sort((a,b)=>(a.categoriaNome||a.tipo||'').localeCompare(b.categoriaNome||b.tipo||'')||(a.serial||'').localeCompare(b.serial||''));return `<div class="card"><div class="row"><div><h2>Equipamentos</h2><p class="hint">Identificação operacional pelo número de série do fabricante.</p></div><div class="inline-actions">${isAdmin()?`<button class="btn ghost" onclick="exportarCSV('equipamentos')">Exportar CSV</button>`:''}<button class="btn" onclick="editarEquipamento()">+ Novo equipamento</button></div></div><div class="tabs"><button class="tab active" onclick="renderEquipTab('lista',this)">Lista</button><button class="tab" onclick="renderEquipTab('agenda',this)">Disponibilidade / agenda</button></div><div id="equipTab">${equipTable(rows)}</div></div>`}
function equipTable(rows){return `<input class="search" id="eqSearch" placeholder="Pesquisar categoria, modelo, fabricante, série ou tensão..." oninput="filterTable('eqTable',this.value)">${rows.length?`<table id="eqTable"><thead><tr><th>Equipamento</th><th>Série</th><th>Situação</th><th>Local atual</th><th>Ações</th></tr></thead><tbody>${rows.map(e=>`<tr data-search="${esc([e.categoriaNome,e.tipo,e.marca,e.modelo,e.serial,e.tensao,e.situacao].join(' '))}"><td><b>${esc(equipName(e.id))}</b><br><span class="muted">${esc(e.tipo||'')}</span></td><td>${esc(e.serial)}</td><td>${tag(e.situacao||'Disponível',statusType(e.situacao))}</td><td>${esc(e.localAtual||'Safety')}</td><td><div class="inline-actions"><button class="btn small ghost" onclick="detalharEquipamento('${e.id}')">Abrir</button><button class="btn small ghost" onclick="editarEquipamento('${e.id}')">Editar</button><button class="btn small" onclick="novoTeste('${e.id}')">Teste</button></div></td></tr>`).join('')}</tbody></table>`:empty('Nenhum equipamento cadastrado.')}`}
function equipmentForm(e={}){const current=e.situacao||'Disponível',manualStatuses=isAdmin()&&!EQUIP_COMMITMENT_STATUSES.has(current)?allowedNext(current,EQUIP_TRANSITIONS):[current];return `<div class="grid2"><div><label>Categoria *</label><select id="eCat"><option value="">Selecione</option>${selectOptions(active('categorias'),e.categoriaId,x=>x.nome)}</select></div><div><label>Tipo / descrição *</label><input id="eTipo" value="${esc(e.tipo||'')}"></div><div><label>Fabricante / marca *</label><input id="eMarca" value="${esc(e.marca||'')}"></div><div><label>Modelo *</label><input id="eModelo" value="${esc(e.modelo||'')}"></div><div><label>Número de série *</label><input id="eSerial" value="${esc(e.serial||'')}"></div><div><label>Tensão / característica</label><input id="eTensao" value="${esc(e.tensao||'')}"></div><div><label>Situação</label><select id="eSituacao" ${(!isAdmin()||EQUIP_COMMITMENT_STATUSES.has(current))?'disabled':''}>${manualStatuses.map(s=>`<option ${current===s?'selected':''}>${s}</option>`).join('')}</select>${EQUIP_COMMITMENT_STATUSES.has(current)?'<span class="hint">Situação controlada pela operação vinculada.</span>':''}</div><div><label>Local atual</label><input id="eLocal" value="${esc(e.localAtual||'Safety')}" ${EQUIP_COMMITMENT_STATUSES.has(current)?'disabled':''}></div></div><label>Observações</label><textarea id="eObs">${esc(e.observacoes||'')}</textarea>`}
async function salvarEquipamento(id){const serial=$('eSerial').value.trim(),tipo=$('eTipo').value.trim(),catId=$('eCat').value,marca=$('eMarca').value.trim(),modelo=$('eModelo').value.trim();if(!serial||!tipo||!catId||!marca||!modelo)return alert('Preencha Categoria, Tipo/descrição, Fabricante, Modelo e Número de série.');const dup=data.equipamentos.find(x=>x.id!==id&&!isArchived(x)&&normalize(x.serial)===normalize(serial));if(dup)return alert('Já existe um equipamento com esse número de série.');const before=id?clone(find('equipamentos',id)):null,cat=find('categorias',catId),situacao=$('eSituacao')?.value||before?.situacao||'Disponível';if(before&&!validateTransition(before.situacao,situacao,EQUIP_TRANSITIONS,'situação do equipamento')&&!EQUIP_COMMITMENT_STATUSES.has(before.situacao))return;const obj={categoriaId:catId,categoriaNome:cat?.nome||'',tipo,marca,modelo,serial,tensao:$('eTensao').value.trim(),situacao,localAtual:$('eLocal')?.value.trim()||before?.localAtual||'Safety',observacoes:$('eObs').value.trim(),ativo:true,arquivado:false};if(id){await setDoc(COLS.equipamentos,id,obj);await audit('editar','Equipamentos',id,`Equipamento série ${serial} atualizado.`,before,obj)}else{const nid=await addDoc(COLS.equipamentos,obj);await audit('criar','Equipamentos',nid,`Equipamento série ${serial} cadastrado.`,null,obj)}fecharModal();await refresh('Equipamento salvo.')}
function novoTeste(equipId){
  const e=find('equipamentos',equipId),cat=find('categorias',e?.categoriaId),items=cat?.itensTeste||[],committed=EQUIP_COMMITMENT_STATUSES.has(e?.situacao),situacoes=committed?[e.situacao]:['Disponível','Aguardando teste','Em manutenção','Indisponível'];
  abrirModal('Registrar teste técnico',`<p><b>${esc(equipName(equipId))}</b></p><p class="hint">Situação atual: ${esc(e.situacao||'—')}${committed?' · O equipamento possui compromisso ativo; o teste não poderá liberá-lo.':''}</p><div class="grid2"><div><label>Data *</label><input id="tData" type="date" value="${todayISO()}"></div><div><label>Tipo *</label><select id="tTipo"><option>Teste de bancada</option><option>Liberação técnica</option><option>Preventiva</option><option>Teste final</option></select></div></div><div class="section-title">Checklist / parâmetros</div>${items.length?`<div class="check-grid">${items.map((x,i)=>`<div><label>${esc(x)}</label><input id="ti${i}" placeholder="Resultado / valor"></div>`).join('')}</div>`:`<div class="notice">Esta categoria ainda não possui modelo de teste configurado.</div>`}<label>Observações</label><textarea id="tObs"></textarea><div class="grid2"><div><label>Resultado *</label><select id="tResultado" onchange="ajustarSituacaoPosTeste()"><option>Aprovado</option><option>Aprovado com observação</option><option>Reprovado</option></select></div><div><label>Situação após o teste *</label><select id="tSituacao" ${committed?'disabled':''}>${situacoes.map(s=>`<option ${s===e.situacao?'selected':''}>${s}</option>`).join('')}</select></div></div>`, `<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarTeste('${equipId}')">Salvar teste</button>`)
}
function ajustarSituacaoPosTeste(){const r=$('tResultado')?.value,s=$('tSituacao');if(!s)return;if(r==='Reprovado'&&s.value==='Disponível')s.value='Em manutenção';if(r!=='Reprovado'&&['Em manutenção','Indisponível'].includes(s.value))s.value='Disponível'}
async function salvarTeste(equipId){try{requireOnline();const e=find('equipamentos',equipId),cat=find('categorias',e?.categoriaId),items=(cat?.itensTeste||[]).map((x,i)=>({item:x,valor:$(`ti${i}`)?.value||''})),resultado=$('tResultado').value,situacao=$('tSituacao').value;if(resultado==='Reprovado'&&situacao==='Disponível')return alert('Um teste reprovado não pode liberar o equipamento como Disponível.');const ref=db.collection(COLS.testes).doc(),obj={equipamentoId:equipId,categoriaId:e.categoriaId,serial:e.serial,data:$('tData').value,tipo:$('tTipo').value,itens,observacoes:$('tObs').value.trim(),resultado,situacaoAnterior:e.situacao,situacaoPosterior:situacao,tecnicoUid:currentUser.uid,tecnicoNome:currentUser.nome,tecnicoMatricula:currentUser.matricula||'',tecnicoFuncao:currentUser.funcao||'',ativo:true,criadoEm:nowISO(),criadoPor:currentUser.uid};const batch=db.batch();batch.set(ref,obj);batch.set(db.collection(COLS.equipamentos).doc(equipId),{situacao,localAtual:situacao==='Disponível'?'Safety':e.localAtual||'Safety',alteradoEm:nowISO(),alteradoPor:currentUser.uid},{merge:true});await batch.commit();await audit('teste','Equipamentos',equipId,`Teste ${obj.tipo}: ${obj.resultado}. Situação ${e.situacao} → ${situacao}.`);fecharModal();await refresh('Teste registrado e situação atualizada.');if(confirm('Deseja assinar eletronicamente este teste como técnico responsável?'))perguntarAssinaturaTecnico('teste',ref.id)}catch(e){console.error(e);alert('Não foi possível salvar o teste técnico: '+e.message)}}

function viewLocacoes(){if(!isAdmin())return empty('Acesso restrito.');const rows=active('locacoes').sort((a,b)=>(b.inicio||'').localeCompare(a.inicio||''));return `<div class="card"><div class="row"><div><h2>Locações</h2><p class="hint">Cada locação representa uma negociação/contrato. Equipamentos com condições diferentes devem ser registrados separadamente.</p></div><div class="inline-actions"><button class="btn ghost" onclick="exportarCSV('locacoes')">Exportar CSV</button><button class="btn" onclick="novaLocacao()">+ Nova locação</button></div></div><input class="search" placeholder="Pesquisar protocolo, cliente, responsável ou série..." oninput="filterTable('locTable',this.value)">${rows.length?`<table id="locTable"><thead><tr><th>Protocolo / Cliente</th><th>Período</th><th>Equipamentos</th><th>Valor mensal</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(l=>`<tr data-search="${esc([l.protocolo,clientName(l.clienteId),l.responsavel,...(l.itens||[]).map(i=>i.serialSnapshot)].join(' '))}"><td><b>${esc(l.protocolo||l.id)}</b><br>${esc(clientName(l.clienteId))}<br><span class="muted">${esc(l.responsavel||'')}</span></td><td>${dateBR(l.inicio)} → ${dateBR(l.termino)}${l.prorrogacoes?.length?`<br><span class="muted">${l.prorrogacoes.length} prorrogação(ões)</span>`:''}</td><td>${(l.itens||[]).map(i=>`<div>${esc(i.serialSnapshot||find('equipamentos',i.equipamentoId)?.serial||'—')} · ${brl(i.valorMensal||0)}</div>`).join('')}</td><td><b>${brl((l.itens||[]).reduce((s,i)=>s+Number(i.valorMensal||0),0))}</b></td><td>${tag(l.status||'Preparação',statusType(l.status))}</td><td><div class="inline-actions"><button class="btn small ghost" onclick="detalharLocacao('${l.id}')">Abrir</button>${!RENTAL_CLOSED_STATUSES.has(l.status)?`<button class="btn small ghost" onclick="editarLocacao('${l.id}')">Editar</button>`:''}</div></td></tr>`).join('')}</tbody></table>`:empty('Nenhuma locação cadastrada.')}</div>`}
function rentalItemRow(i={},idx=Date.now(),locId=''){const available=active('equipamentos').filter(e=>e.id===i.equipamentoId||e.situacao==='Disponível');const sid=`liEquip_${String(idx).replace(/\W/g,'')}`;return `<div class="grid3 rental-item" data-idx="${esc(idx)}"><div><label>Equipamento *</label><input class="search compact" placeholder="Pesquisar categoria, modelo, fabricante, série..." oninput="filterSelectOptions('${sid}',this.value)"><select class="liEquip" id="${sid}"><option value="">Selecione</option>${selectOptions(available,i.equipamentoId,e=>equipName(e.id))}</select></div><div><label>Valor mensal negociado *</label><input class="liValor" inputmode="decimal" value="${esc(i.valorMensal||'')}"></div><div><label>&nbsp;</label><button type="button" class="btn danger small" onclick="this.closest('.rental-item').remove()">Remover</button></div></div>`}
function rentalItemsHtml(items=[],locId=''){return `<div id="locItens">${items.map((i,idx)=>rentalItemRow(i,idx,locId)).join('')}</div><button type="button" class="btn small ghost" onclick="adicionarItemLocacao()">+ Adicionar equipamento</button>`}
function editarLocacao(id=''){const l=id?find('locacoes',id):{},cli=find('clientes',l.clienteId)||{},current=l.status||'Preparação',statuses=id?allowedNext(current,RENTAL_TRANSITIONS):['Preparação','Reservada','Liberada para entrega','Ativa'];abrirModal(id?`Editar locação · ${l.protocolo||id}`:'Nova locação',`<div class="grid2"><div><label>Cliente *</label><input class="search compact" placeholder="Pesquisar cliente, CPF/CNPJ..." oninput="filterSelectOptions('lCliente',this.value)"><select id="lCliente" onchange="preencherDadosLocCliente()"><option value="">Selecione</option>${selectOptions(active('clientes').filter(c=>c.cadastroNivel!=='rapido'||c.cpfCnpj),l.clienteId,c=>c.nomeRazao+' · '+(c.cpfCnpj||''))}</select></div><div><label>Responsável</label><input id="lResp" value="${esc(l.responsavel||cli.responsavel||'')}"></div><div><label>Data inicial *</label><input id="lInicio" type="date" value="${esc(l.inicio||todayISO())}" onchange="updateRentalDocType()"></div><div><label>Data final prevista *</label><input id="lTermino" type="date" value="${esc(l.termino||'')}" onchange="updateRentalDocType()"></div><div><label>Tipo de documento *</label><select id="lDocTipo"><option value="30dias" ${l.tipoDocumento==='30dias'?'selected':''}>Comprovante de entrega / até 30 dias</option><option value="contrato" ${l.tipoDocumento==='contrato'?'selected':''}>Contrato de locação</option></select></div><div><label>Dia de vencimento mensal *</label><input id="lDiaVenc" type="number" min="1" max="31" value="${esc(l.diaVencimento||15)}"></div><div><label>Status *</label><select id="lStatus">${statuses.map(s=>`<option ${current===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="section-title">Endereço de instalação</div>${addressForm('lInst',l.enderecoInstalacao||(cli.enderecosInstalacao||[])[0]||{})}<div class="section-title">Equipamentos</div>${rentalItemsHtml(l.itens||[],id)}<label>Observações</label><textarea id="lObs">${esc(l.observacoes||'')}</textarea>`,`<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarLocacao('${id}')">Salvar</button>`);setTimeout(updateRentalDocType,0)}
function updateRentalDocType(){const a=$('lInicio')?.value,b=$('lTermino')?.value,s=$('lDocTipo');if(!a||!b||!s)return;const d=daysBetween(a,b);if(d>=0)s.value=d<=30?'30dias':'contrato'}
function adicionarItemLocacao(){const d=document.createElement('div');d.innerHTML=rentalItemRow({},Date.now());$('locItens').appendChild(d.firstElementChild)}
function collectRentalItems(){return [...document.querySelectorAll('.rental-item')].map(r=>{const eid=r.querySelector('.liEquip').value,e=find('equipamentos',eid);return{equipamentoId:eid,serialSnapshot:e?.serial||'',descricaoSnapshot:equipName(eid),valorMensal:num(r.querySelector('.liValor').value)}}).filter(x=>x.equipamentoId)}
async function salvarLocacao(id){
  try{
    requireOnline();
    const cli=$('lCliente').value,itens=collectRentalItems(),inicio=$('lInicio').value,termino=$('lTermino').value,status=$('lStatus').value;
    if(!cli||!inicio||!termino||!itens.length)return alert('Informe cliente, período e ao menos um equipamento.');
    if(termino<inicio)return alert('A data final não pode ser anterior à inicial.');
    if(new Set(itens.map(i=>i.equipamentoId)).size!==itens.length)return alert('O mesmo equipamento não pode ser incluído duas vezes na locação.');
    const before=id?clone(find('locacoes',id)):null,oldIds=(before?.itens||[]).map(x=>x.equipamentoId);
    const conflict=itens.find(i=>equipmentHasConflict(i.equipamentoId,inicio,termino,id));
    if(conflict)return alert(`O equipamento ${equipName(conflict.equipamentoId)} já possui compromisso nesse período.`);
    for(const i of itens){
      const e=find('equipamentos',i.equipamentoId),alreadyInThisRental=oldIds.includes(i.equipamentoId);
      if(!alreadyInThisRental&&e?.situacao!=='Disponível')return alert(`O equipamento ${equipName(e.id)} não está disponível para uma nova locação.`);
    }
    if(before&&!validateTransition(before.status,status,RENTAL_TRANSITIONS,'status da locação'))return;
    const protocolo=before?.protocolo||await nextProtocol('LOC'),obj={clienteId:cli,protocolo,responsavel:$('lResp').value.trim(),inicio,termino,tipoDocumento:$('lDocTipo').value,diaVencimento:Number($('lDiaVenc').value||15),status,enderecoInstalacao:modalAddress('lInst'),itens,observacoes:$('lObs').value.trim(),prorrogacoes:before?.prorrogacoes||[],responsaveisHistorico:before?.responsaveisHistorico||[],ativo:true,arquivado:false};
    const locRef=id?db.collection(COLS.locacoes).doc(id):db.collection(COLS.locacoes).doc(),lid=locRef.id,batch=db.batch();
    batch.set(locRef,{...obj,...(id?{alteradoEm:nowISO(),alteradoPor:currentUser.uid}:{criadoEm:nowISO(),criadoPor:currentUser.uid})},{merge:!!id});
    const newIds=itens.map(x=>x.equipamentoId),allIds=new Set([...oldIds,...newIds]);
    for(const eid of allIds){
      const was=oldIds.includes(eid),now=newIds.includes(eid),eref=db.collection(COLS.equipamentos).doc(eid),e=find('equipamentos',eid);let upd=null;
      if(was&&!now)upd={situacao:before?.status==='Ativa'?'Aguardando teste':'Disponível',localAtual:'Safety'};
      else if(now){
        if(['Preparação','Reservada','Aguardando teste','Liberada para entrega'].includes(status))upd={situacao:'Reservado',localAtual:'Safety'};
        else if(status==='Ativa')upd={situacao:'Alugado',localAtual:formatAddress(obj.enderecoInstalacao)};
        else if(['Encerrada','Cancelada'].includes(status))upd={situacao:(before?.status==='Ativa'||e?.situacao==='Alugado')?'Aguardando teste':'Disponível',localAtual:'Safety'};
      }
      if(upd)batch.set(eref,{...upd,alteradoEm:nowISO(),alteradoPor:currentUser.uid},{merge:true});
    }
    await batch.commit();
    await audit(id?'editar':'criar','Locações',lid,`${protocolo} de ${clientName(cli)} ${id?'atualizada':'criada'}.`,before,obj);
    fecharModal();await refresh(`Locação ${protocolo} salva.`);
  }catch(e){console.error(e);alert('Não foi possível salvar a locação: '+e.message)}
}
function equipmentHasConflict(eid,start,end,ignoreLoc=''){return active('locacoes').some(l=>l.id!==ignoreLoc&&!RENTAL_CLOSED_STATUSES.has(l.status)&&(l.itens||[]).some(i=>i.equipamentoId===eid)&&!(end<l.inicio||start>l.termino))}
function detalharLocacao(id){const l=find('locacoes',id);if(!l)return;const cb=active('cobrancas').filter(x=>x.locacaoId===id).sort((a,b)=>(b.competencia||'').localeCompare(a.competencia||'')),mov=active('movimentos').filter(x=>x.locacaoId===id).sort((a,b)=>(b.em||'').localeCompare(a.em||''));let actions=`<button class="btn ghost" onclick="fecharModal()">Fechar</button>`;if(!RENTAL_CLOSED_STATUSES.has(l.status)){actions+=`<button class="btn ghost" onclick="prorrogarLocacao('${id}')">Prorrogar</button><button class="btn ghost" onclick="trocarResponsavelLocacao('${id}')">Trocar responsável</button><button class="btn ghost" onclick="alterarEnderecoLocacao('${id}')">Alterar endereço</button><button class="btn ghost" onclick="trocarEquipamento('${id}')">Substituir equipamento</button><button class="btn ghost" onclick="registrarVistoria('${id}')">Vistoria</button><button class="btn gold" onclick="gerarDocumentoLocacao('${id}')">Gerar documento</button><button class="btn" onclick="fecharModal();editarLocacao('${id}')">Editar</button>`;if(l.status==='Ativa')actions+=`<button class="btn danger" onclick="encerrarLocacao('${id}')">Registrar devolução</button>`;if(l.status!=='Ativa')actions+=`<button class="btn danger" onclick="cancelarLocacao('${id}')">Cancelar locação</button>`}abrirModal(`Locação · ${l.protocolo||id}`,`<div class="grid2"><div><p>${tag(l.status,statusType(l.status))}</p><p><b>${esc(clientName(l.clienteId))}</b></p><p><b>${dateBR(l.inicio)} → ${dateBR(l.termino)}</b></p><p>${esc(formatAddress(l.enderecoInstalacao))}</p><p>Responsável: ${esc(l.responsavel||'—')}</p></div><div class="metric-row"><div class="metric"><span>Valor mensal</span><strong>${brl((l.itens||[]).reduce((s,i)=>s+Number(i.valorMensal||0),0))}</strong></div><div class="metric"><span>Cobranças</span><strong>${cb.length}</strong></div></div></div><div class="section-title">Equipamentos</div>${(l.itens||[]).map(i=>`<div class="metric"><span>${esc(i.serialSnapshot||'')}</span><strong style="font-size:13px">${esc(i.descricaoSnapshot||equipName(i.equipamentoId))} · ${brl(i.valorMensal)}</strong></div>`).join('')}<div class="section-title">Cobranças recentes</div>${cb.length?cb.slice(0,5).map(c=>`<div class="metric"><span>${monthLabel(c.competencia)} · ${dateBR(c.vencimento)}</span><strong style="font-size:13px">${brl(c.valorContrato||c.valor)} · ${esc(paymentStatus(c))}</strong></div>`).join(''):empty('Sem cobranças.')}<div class="section-title">Movimentações</div>${mov.length?`<div class="timeline">${mov.map(m=>`<div class="timeline-item"><strong>${esc(m.tipo)} · ${dateTimeBR(m.em)}</strong><p>${esc(m.descricao||'')}</p></div>`).join('')}</div>`:empty('Sem movimentações.')}`,actions)}
async function prorrogarLocacao(id){const l=find('locacoes',id),nova=prompt('Nova data final (AAAA-MM-DD):',l.termino);if(!nova||nova<=l.termino)return;if((l.itens||[]).some(i=>equipmentHasConflict(i.equipamentoId,l.termino,nova,id)))return alert('Existe conflito de agenda para um dos equipamentos no novo período.');const hist=[...(l.prorrogacoes||[]),{de:l.termino,para:nova,em:nowISO(),uid:currentUser.uid,nome:currentUser.nome}];requireOnline();const batch=db.batch();batch.set(db.collection(COLS.locacoes).doc(id),{termino:nova,prorrogacoes:hist,alteradoEm:nowISO(),alteradoPor:currentUser.uid},{merge:true});const mref=db.collection(COLS.movimentos).doc();batch.set(mref,{tipo:'Prorrogação',locacaoId:id,clienteId:l.clienteId,sigiloFinanceiro:true,descricao:`Prazo alterado de ${dateBR(l.termino)} para ${dateBR(nova)} por ${currentUser.nome}.`,em:nowISO(),ativo:true,criadoPor:currentUser.uid});await batch.commit();await audit('prorrogar','Locações',id,`${l.protocolo||id}: ${dateBR(l.termino)} → ${dateBR(nova)}.`);fecharModal();await refresh('Locação prorrogada e movimentação registrada.')}
async function trocarResponsavelLocacao(id){const l=find('locacoes',id),novo=prompt('Nome do novo responsável:',l.responsavel||'');if(!novo||novo===l.responsavel)return;const inicio=prompt('Data de início da responsabilidade (AAAA-MM-DD):',todayISO());if(!inicio)return;const hist=[...(l.responsaveisHistorico||[]),{responsavelAnterior:l.responsavel||'',responsavelNovo:novo,inicio,em:nowISO(),uid:currentUser.uid,nome:currentUser.nome}];requireOnline();const mref=db.collection(COLS.movimentos).doc(),batch=db.batch();batch.set(db.collection(COLS.locacoes).doc(id),{responsavel:novo,responsaveisHistorico:hist,alteradoEm:nowISO(),alteradoPor:currentUser.uid},{merge:true});batch.set(mref,{tipo:'Alteração de responsável',locacaoId:id,clienteId:l.clienteId,sigiloFinanceiro:true,responsavelAnterior:l.responsavel||'',responsavelNovo:novo,inicioResponsabilidade:inicio,descricao:`Responsável alterado de ${l.responsavel||'—'} para ${novo}, com vigência em ${dateBR(inicio)}.`,em:nowISO(),ativo:true,criadoPor:currentUser.uid});await batch.commit();await audit('troca_responsavel','Locações',id,`${l.protocolo||id}: responsável ${l.responsavel||'—'} → ${novo}.`);fecharModal();await refresh(null,false);abrirModal('Responsável atualizado',`<p>A alteração foi registrada no histórico da locação <b>${esc(l.protocolo||id)}</b>.</p>`,`<button class="btn ghost" onclick="fecharModal()">Concluir</button><button class="btn" onclick="fecharModal();gerarAditivoResponsavel('${id}','${mref.id}')">Gerar termo aditivo</button>`)}
async function encerrarLocacao(id){const l=find('locacoes',id);if(!l||l.status!=='Ativa')return;if(!confirm('Confirmar a devolução dos equipamentos e encerrar a locação? Os equipamentos ficarão Aguardando teste.'))return;requireOnline();const batch=db.batch();batch.set(db.collection(COLS.locacoes).doc(id),{status:'Encerrada',terminoReal:todayISO(),encerradoEm:nowISO(),encerradoPor:currentUser.uid,alteradoEm:nowISO()},{merge:true});for(const i of l.itens||[])batch.set(db.collection(COLS.equipamentos).doc(i.equipamentoId),{situacao:'Aguardando teste',localAtual:'Safety',alteradoEm:nowISO(),alteradoPor:currentUser.uid},{merge:true});const mref=db.collection(COLS.movimentos).doc();batch.set(mref,{tipo:'Devolução de locação',locacaoId:id,clienteId:l.clienteId,sigiloFinanceiro:true,descricao:`Equipamentos devolvidos. ${l.protocolo||id} encerrada; ativos aguardam teste técnico.`,em:nowISO(),ativo:true,criadoPor:currentUser.uid});await batch.commit();await audit('encerrar','Locações',id,`${l.protocolo||id} encerrada por devolução.`);fecharModal();await refresh('Devolução registrada. Equipamentos aguardam teste técnico.')}
async function cancelarLocacao(id){const l=find('locacoes',id);if(!l||l.status==='Ativa')return alert('Locação ativa deve ser encerrada pelo fluxo de devolução.');if(!confirm('Cancelar esta locação/reserva?'))return;requireOnline();const batch=db.batch();batch.set(db.collection(COLS.locacoes).doc(id),{status:'Cancelada',canceladaEm:nowISO(),canceladaPor:currentUser.uid,alteradoEm:nowISO()},{merge:true});for(const i of l.itens||[]){const e=find('equipamentos',i.equipamentoId);if(e?.situacao==='Reservado')batch.set(db.collection(COLS.equipamentos).doc(i.equipamentoId),{situacao:'Disponível',localAtual:'Safety',alteradoEm:nowISO(),alteradoPor:currentUser.uid},{merge:true})}const mref=db.collection(COLS.movimentos).doc();batch.set(mref,{tipo:'Cancelamento de locação',locacaoId:id,clienteId:l.clienteId,sigiloFinanceiro:true,descricao:`${l.protocolo||id} cancelada; reservas liberadas.`,em:nowISO(),ativo:true,criadoPor:currentUser.uid});await batch.commit();await audit('cancelar','Locações',id,`${l.protocolo||id} cancelada.`);fecharModal();await refresh('Locação cancelada e equipamentos reservados liberados.')}
function trocarEquipamento(locId){const l=find('locacoes',locId),available=active('equipamentos').filter(e=>e.situacao==='Disponível');abrirModal('Substituição de equipamento',`<div class="grid2"><div><label>Equipamento que será retirado *</label><select id="trOld">${(l.itens||[]).map(i=>`<option value="${i.equipamentoId}">${esc(i.descricaoSnapshot||equipName(i.equipamentoId))}</option>`).join('')}</select></div><div><label>Novo equipamento disponível *</label><input class="search compact" placeholder="Pesquisar categoria, modelo, fabricante, série..." oninput="filterSelectOptions('trNew',this.value)"><select id="trNew"><option value="">Selecione</option>${selectOptions(available,'',e=>equipName(e.id))}</select></div></div><label>Motivo / observação *</label><textarea id="trMotivo"></textarea>`,`<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarTroca('${locId}')">Registrar troca</button>`)}
async function salvarTroca(locId){try{const l=find('locacoes',locId),oldId=$('trOld').value,newId=$('trNew').value,motivo=$('trMotivo').value.trim();if(!newId||!motivo)return alert('Selecione o equipamento substituto e informe o motivo.');if(equipmentHasConflict(newId,l.inicio,l.termino,locId))return alert('O equipamento substituto possui conflito de agenda no período desta locação.');const newE=find('equipamentos',newId);if(newE?.situacao!=='Disponível')return alert('O equipamento substituto não está mais disponível. Atualize a tela.');requireOnline();const itens=(l.itens||[]).map(i=>i.equipamentoId===oldId?{...i,equipamentoId:newId,serialSnapshot:newE.serial,descricaoSnapshot:equipName(newId)}:i),mid=db.collection(COLS.movimentos).doc(),batch=db.batch();batch.set(db.collection(COLS.locacoes).doc(locId),{itens,alteradoEm:nowISO(),alteradoPor:currentUser.uid},{merge:true});batch.set(db.collection(COLS.equipamentos).doc(oldId),{situacao:'Aguardando teste',localAtual:'Safety',alteradoEm:nowISO(),alteradoPor:currentUser.uid},{merge:true});batch.set(db.collection(COLS.equipamentos).doc(newId),{situacao:l.status==='Ativa'?'Alugado':'Reservado',localAtual:l.status==='Ativa'?formatAddress(l.enderecoInstalacao):'Safety',alteradoEm:nowISO(),alteradoPor:currentUser.uid},{merge:true});batch.set(mid,{tipo:'Substituição',locacaoId:locId,clienteId:l.clienteId,sigiloFinanceiro:true,equipamentoAnteriorId:oldId,equipamentoNovoId:newId,equipamentoId:newId,motivo,descricao:`${equipName(oldId)} substituído por ${equipName(newId)}. Motivo: ${motivo}`,em:nowISO(),assinaturaClienteVetorial:'',ativo:true,criadoPor:currentUser.uid});await batch.commit();await audit('substituir','Locações',locId,`Equipamento substituído em ${l.protocolo||locId}. Movimento ${mid.id}.`);fecharModal();await refresh(null,false);abrirModal('Substituição registrada',`<p>A substituição foi salva. O equipamento retirado ficou <b>Aguardando teste</b>.</p><p>${tag('Assinatura pendente','warn')}</p>`,`<button class="btn ghost" onclick="fecharModal()">Concluir sem assinatura</button><button class="btn ghost" onclick="fecharModal();perguntarAssinaturaClienteMovimento('${mid.id}')">Assinar cliente agora</button><button class="btn" onclick="fecharModal();gerarDocumentoMovimento('${mid.id}')">Gerar documento</button>`)}catch(e){console.error(e);alert('Não foi possível registrar a substituição: '+e.message)}}

function viewAssistencias(){const rows=active('assistencias').sort((a,b)=>(b.entrada||'').localeCompare(a.entrada||''));return `<div class="card"><div class="row"><div><h2>Assistência Técnica</h2><p class="hint">Particular, garantia, diagnóstico, orçamento, manutenção, testes e empréstimos, com histórico permanente por número de série.</p></div><div class="inline-actions">${isAdmin()?`<button class="btn ghost" onclick="exportarCSV('assistencias')">Exportar CSV</button>`:''}<button class="btn" onclick="editarAssistencia()">+ Nova entrada</button></div></div><input class="search" placeholder="Pesquisar protocolo, cliente, série, equipamento ou status..." oninput="filterTable('assTable',this.value)">${rows.length?`<table id="assTable"><thead><tr><th>Protocolo / Entrada</th><th>Cliente</th><th>Equipamento</th><th>Tipo</th><th>Status</th><th>Orçamento</th><th>Ações</th></tr></thead><tbody>${rows.map(a=>`<tr data-search="${esc([a.protocolo,clientName(a.clienteId),a.serial,a.equipamentoTipo,a.marca,a.modelo,a.status].join(' '))}"><td><b>${esc(a.protocolo||a.id)}</b><br><span class="muted">${dateBR(a.entrada)}</span></td><td><b>${esc(clientName(a.clienteId))}</b></td><td>${esc([a.equipamentoTipo,a.marca,a.modelo].filter(Boolean).join(' '))}<br><span class="muted">Série ${esc(a.serial||'—')}</span></td><td>${tag(a.tipoAtendimento||'Particular','info')}</td><td>${tag(a.status||'Recebido',statusType(a.status))}</td><td>${a.orcamentoValor?brl(a.orcamentoValor):'—'}<br><span class="muted">${esc(a.orcamentoStatus||'')}</span></td><td><div class="inline-actions"><button class="btn small ghost" onclick="detalharAssistencia('${a.id}')">Abrir</button>${!['Entregue','Cancelada'].includes(a.status)?`<button class="btn small ghost" onclick="editarAssistencia('${a.id}')">Editar</button>`:''}</div></td></tr>`).join('')}</tbody></table>`:empty('Nenhum atendimento cadastrado.')}</div>`}
function quickClientFields(){return `<div id="quickClientBox" class="notice blue hidden"><h4>Cliente rápido / avulso</h4><div class="grid2"><div><label>Nome / Razão Social *</label><input id="qcNome"></div><div><label>Telefone / WhatsApp *</label><input id="qcTel"></div><div><label>CPF/CNPJ</label><input id="qcCpf"></div><div><label>E-mail</label><input id="qcEmail" type="email"></div><div><label>Endereço</label><input id="qcEndereco" placeholder="Logradouro, número, bairro, cidade"></div></div><p class="hint">O cadastro rápido poderá ser completado posteriormente sem perder o histórico.</p></div>`}
function toggleQuickClient(){const b=$('quickClientBox');if(b)b.classList.toggle('hidden')}
function warrantyFields(a={}){return `<div id="warrantyBox" class="${a.tipoAtendimento==='Garantia'?'':'hidden'}"><div class="section-title">Garantia do fabricante</div><div class="grid2"><div><label>Nota fiscal apresentada? *</label><select id="aNF"><option value="Não" ${a.notaFiscalApresentada!=='Sim'?'selected':''}>Não</option><option value="Sim" ${a.notaFiscalApresentada==='Sim'?'selected':''}>Sim</option></select></div><div><label>Fabricante da garantia *</label><input id="aFabGarantia" value="${esc(a.fabricanteGarantia||'')}"></div><div><label>Contato / responsável no fabricante</label><input id="aContatoFab" value="${esc(a.contatoFabricante||'')}"></div><div><label>Referência / protocolo</label><input id="aGarantiaRef" value="${esc(a.garantiaReferencia||'')}"></div><div><label>Data do contato</label><input id="aDataContato" type="date" value="${esc(a.dataContatoFabricante||'')}"></div><div><label>Status da autorização *</label><select id="aAutStatus"><option value="Aguardando" ${a.autorizacaoFabricante!=='Autorizado'&&a.autorizacaoFabricante!=='Não autorizado'?'selected':''}>Aguardando</option><option value="Autorizado" ${a.autorizacaoFabricante==='Autorizado'?'selected':''}>Autorizado</option><option value="Não autorizado" ${a.autorizacaoFabricante==='Não autorizado'?'selected':''}>Não autorizado</option></select></div></div><label>Observações da autorização</label><textarea id="aAutObs">${esc(a.observacaoAutorizacao||'')}</textarea></div>`}
function toggleWarrantyFields(){const b=$('warrantyBox');if(b)b.classList.toggle('hidden',$('aTipo').value!=='Garantia')}
function updateAssistHistoryHint(){const serial=$('aSerial')?.value.trim(),box=$('serialHistoryHint');if(!box)return;if(!serial){box.innerHTML='';return}const hist=active('assistencias').filter(a=>normalize(a.serial)===normalize(serial)&&a.id!==window.__editingAssistId).sort((a,b)=>(b.entrada||'').localeCompare(a.entrada||''));box.innerHTML=hist.length?`<div class="notice blue"><b>Histórico encontrado:</b> ${hist.length} atendimento(s) anterior(es) para esta série. Último: ${esc(hist[0].protocolo||hist[0].id)} em ${dateBR(hist[0].entrada)} — ${esc(hist[0].defeitoRelatado||hist[0].diagnostico||'sem descrição')}.</div>`:''}
function editarAssistencia(id=''){const a=id?find('assistencias',id):{},current=a.status||'Recebido',statuses=id?allowedNext(current,ASSIST_TRANSITIONS):['Recebido'];window.__editingAssistId=id||'';abrirModal(id?`Editar assistência · ${a.protocolo||id}`:'Nova entrada de assistência',`<div class="grid2"><div><label>Cliente *</label><input class="search compact" placeholder="Pesquisar cliente, CPF/CNPJ, telefone..." oninput="filterSelectOptions('aCliente',this.value)"><select id="aCliente"><option value="">Selecione</option>${selectOptions(active('clientes'),a.clienteId,c=>`${c.nomeRazao} · ${c.cpfCnpj||c.telefone||''}`)}</select><button type="button" class="link-btn inline-link" onclick="toggleQuickClient()">+ Usar cliente rápido / avulso</button></div><div><label>Tipo de atendimento *</label><select id="aTipo" onchange="toggleWarrantyFields()"><option ${a.tipoAtendimento!=='Garantia'?'selected':''}>Particular</option><option ${a.tipoAtendimento==='Garantia'?'selected':''}>Garantia</option></select></div><div><label>Data de entrada *</label><input id="aEntrada" type="date" value="${esc(a.entrada||todayISO())}"></div><div><label>Status *</label><select id="aStatus">${statuses.map(s=>`<option ${current===s?'selected':''}>${s}</option>`).join('')}</select></div><div><label>Categoria *</label><select id="aCat"><option value="">Selecione</option>${selectOptions(active('categorias'),a.categoriaId,c=>c.nome)}</select></div><div><label>Descrição do equipamento *</label><input id="aEqTipo" value="${esc(a.equipamentoTipo||'')}" placeholder="Ex.: Autoclave 21 L"></div><div><label>Fabricante / marca *</label><input id="aMarca" value="${esc(a.marca||'')}"></div><div><label>Modelo *</label><input id="aModelo" value="${esc(a.modelo||'')}"></div><div><label>Número de série *</label><input id="aSerial" value="${esc(a.serial||'')}" oninput="updateAssistHistoryHint()"></div><div><label>Acessórios recebidos</label><input id="aAcess" value="${esc(a.acessorios||'')}"></div></div>${quickClientFields()}<div id="serialHistoryHint"></div>${warrantyFields(a)}<label>Defeito relatado pelo cliente *</label><textarea id="aDefeito">${esc(a.defeitoRelatado||'')}</textarea><label>Condição / observações de entrada</label><textarea id="aCondEntrada">${esc(a.condicaoEntrada||'')}</textarea><label>Diagnóstico técnico</label><textarea id="aDiag">${esc(a.diagnostico||'')}</textarea><div class="grid2"><div><label>Valor do orçamento</label><input id="aOrcValor" value="${esc(a.orcamentoValor||'')}"></div><div><label>Status do orçamento</label><select id="aOrcStatus"><option></option><option ${a.orcamentoStatus==='Aguardando cliente'?'selected':''}>Aguardando cliente</option><option ${a.orcamentoStatus==='Aprovado'?'selected':''}>Aprovado</option><option ${a.orcamentoStatus==='Recusado'?'selected':''}>Recusado</option></select></div></div><label>Serviços propostos / executados</label><textarea id="aServicos">${esc(a.servicos||'')}</textarea><label>Observações</label><textarea id="aObs">${esc(a.observacoes||'')}</textarea>`,`<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarAssistencia('${id}')">Salvar</button>`);setTimeout(()=>{toggleWarrantyFields();updateAssistHistoryHint()},0)}
async function createQuickClientFromAssist(){const nome=$('qcNome')?.value.trim(),tel=$('qcTel')?.value.trim();if(!nome||!tel)throw new Error('No cliente rápido, informe Nome/Razão Social e Telefone/WhatsApp.');const same=active('clientes').find(c=>normalizedPhone(c.telefone)===normalizedPhone(tel));if(same){if(confirm(`Já existe ${same.nomeRazao} com este telefone. Deseja usar o cadastro existente?`))return same.id}const cpf=$('qcCpf')?.value.trim()||'';if(cpf){const dup=active('clientes').find(c=>normalizeDoc(c.cpfCnpj)===normalizeDoc(cpf));if(dup){if(confirm(`Já existe ${dup.nomeRazao} com este CPF/CNPJ. Deseja usar o cadastro existente?`))return dup.id;throw new Error('CPF/CNPJ já cadastrado.')}}const enderecoTexto=$('qcEndereco')?.value.trim()||'';const id=await addDoc(COLS.clientes,{tipoPessoa:cpf&&cpf.replace(/\D/g,'').length>11?'PJ':'PF',cadastroNivel:'rapido',nomeRazao:nome,cpfCnpj:cpf,telefone:tel,email:$('qcEmail')?.value.trim()||'',enderecoCadastral:{logradouro:enderecoTexto},enderecosInstalacao:[],responsavel:'',historicoCadastral:[],origem:'Assistência técnica',ativo:true,arquivado:false});await audit('criar_rapido','Clientes',id,`Cliente rápido ${nome} criado pela Assistência.`);return id}
