function registrarTesteAssistencia(aid){const a=find('assistencias',aid),cat=find('categorias',a.categoriaId),items=cat?.itensTeste||[];abrirModal('Teste técnico da assistência',`<p>${esc([a.equipamentoTipo,a.marca,a.modelo].filter(Boolean).join(' '))} · Série ${esc(a.serial)}</p><div class="grid2"><div><label>Data *</label><input id="atData" type="date" value="${todayISO()}"></div><div><label>Tipo *</label><select id="atTipo"><option>Teste de bancada</option><option>Teste final</option><option>Manutenção preventiva</option></select></div></div>${items.length?items.map((x,i)=>`<label>${esc(x)}</label><input id="ati${i}">`).join(''):''}<label>Observações</label><textarea id="atObs"></textarea><label>Resultado *</label><select id="atResultado"><option>Aprovado</option><option>Aprovado com observação</option><option>Reprovado</option></select>`,`<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarTesteAssistencia('${aid}')">Salvar</button>`)}
async function salvarTesteAssistencia(aid){
  try{
    requireOnline();
    const a=find('assistencias',aid),cat=find('categorias',a.categoriaId),items=(cat?.itensTeste||[]).map((x,i)=>({item:x,valor:$(`ati${i}`)?.value||''})),resultado=$('atResultado').value,ref=db.collection(COLS.testes).doc(),obj={assistenciaId:aid,clienteId:a.clienteId,categoriaId:a.categoriaId,serial:a.serial,data:$('atData').value,tipo:$('atTipo').value,itens,observacoes:$('atObs').value.trim(),resultado,tecnicoUid:currentUser.uid,tecnicoNome:currentUser.nome,tecnicoMatricula:currentUser.matricula||'',tecnicoFuncao:currentUser.funcao||'',ativo:true,criadoEm:nowISO(),criadoPor:currentUser.uid};
    let desired=a.status;
    if(obj.tipo==='Teste final'&&resultado!=='Reprovado'&&['Em manutenção','Em testes'].includes(a.status))desired='Liberado';
    if(resultado==='Reprovado'&&['Em testes','Liberado'].includes(a.status))desired='Em manutenção';
    const batch=db.batch();batch.set(ref,obj);if(desired!==a.status)batch.set(db.collection(COLS.assistencias).doc(aid),{status:desired,alteradoEm:nowISO(),alteradoPor:currentUser.uid},{merge:true});await batch.commit();
    await audit('teste','Assistência',aid,`Teste ${obj.tipo}: ${obj.resultado}${desired!==a.status?`; status → ${desired}`:''}.`);fecharModal();await refresh('Teste registrado.');if(confirm('Deseja assinar eletronicamente este teste como técnico responsável?'))perguntarAssinaturaTecnico('teste',ref.id)
  }catch(e){console.error(e);alert('Não foi possível salvar o teste: '+e.message)}
}


function viewCobrancas(){if(!isAdmin())return empty('Acesso restrito.');const mes=window.__cobMes||monthKey(),rows=active('cobrancas').filter(x=>x.competencia===mes).sort((a,b)=>(a.vencimento||'').localeCompare(b.vencimento||'')),paid=rows.filter(x=>x.pagoEm),open=rows.filter(x=>!x.pagoEm),late=rows.filter(x=>paymentStatus(x)==='Inadimplente');return `<div class="card"><div class="row"><div><h2>Cobranças</h2><p class="hint">Valor contratual preservado; valor atualizado e valor pago são registrados separadamente.</p></div><div class="inline-actions"><button class="btn ghost" onclick="exportarCSV('cobrancas')">Exportar CSV</button><button class="btn ghost" onclick="gerarCobrancasMes('${mes}')">Gerar cobranças do mês</button><button class="btn" onclick="editarCobranca('', '${mes}')">+ Nova cobrança</button></div></div><div class="toolbar"><div><label>Competência</label><input type="month" value="${mes}" onchange="window.__cobMes=this.value;render()"></div></div><div class="metric-row"><div class="metric"><span>Total</span><strong>${rows.length}</strong></div><div class="metric"><span>Pagos</span><strong>${paid.length}</strong></div><div class="metric"><span>Falta pagar</span><strong>${open.length}</strong></div><div class="metric"><span>Inadimplentes</span><strong>${late.length}</strong></div><div class="metric"><span>Previsto</span><strong>${brl(rows.reduce((s,x)=>s+Number(x.valorContrato||x.valor||0),0))}</strong></div><div class="metric"><span>Recebido</span><strong>${brl(paid.reduce((s,x)=>s+Number(x.valorPago||0),0))}</strong></div></div><input class="search" placeholder="Pesquisar cliente, locação ou status..." oninput="filterTable('cbTable',this.value)">${rows.length?`<table id="cbTable"><thead><tr><th>Cliente / Locação</th><th>Valores</th><th>Vencimento</th><th>Pagamento</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${rows.map(c=>`<tr data-search="${esc([clientName(c.clienteId),c.locacaoProtocolo,c.locacaoId,paymentStatus(c)].join(' '))}"><td><b>${esc(clientName(c.clienteId))}</b><br><span class="muted">${esc(c.locacaoProtocolo||c.locacaoId||'Manual')}</span></td><td>Contrato: <b>${brl(c.valorContrato||c.valor)}</b>${c.valorAtualizado?`<br>Atualizado: ${brl(c.valorAtualizado)}`:''}${c.pagoEm?`<br>Pago: ${brl(c.valorPago||0)}`:''}</td><td>${dateBR(c.vencimento)}</td><td>${dateBR(c.pagoEm)}</td><td>${tag(paymentStatus(c),statusType(paymentStatus(c)))}</td><td><div class="inline-actions">${!c.pagoEm?`<button class="btn small" onclick="registrarPagamento('${c.id}')">Registrar pagamento</button>`:`<button class="btn small ghost" onclick="estornarPagamento('${c.id}')">Estornar</button>`}<button class="btn small ghost" onclick="editarCobranca('${c.id}','${mes}')">Editar</button></div></td></tr>`).join('')}</tbody></table>`:empty('Nenhuma cobrança nesta competência.')}</div>`}
function editarCobranca(id='',mes=monthKey()){const c=id?find('cobrancas',id):{};abrirModal(id?'Editar cobrança':'Nova cobrança',`<div class="grid2"><div><label>Cliente *</label><input class="search compact" placeholder="Pesquisar cliente..." oninput="filterSelectOptions('cbCli',this.value)"><select id="cbCli" onchange="atualizarLocacoesCobranca()"><option value="">Selecione</option>${selectOptions(active('clientes'),c.clienteId,x=>x.nomeRazao+' · '+(x.cpfCnpj||''))}</select></div><div><label>Locação</label><select id="cbLoc" onchange="preencherValorCobranca()"><option value="">Sem vínculo</option></select></div><div><label>Competência *</label><input id="cbComp" type="month" value="${esc(c.competencia||mes)}"></div><div><label>Vencimento *</label><input id="cbVenc" type="date" value="${esc(c.vencimento||'')}"></div><div><label>Valor da locação *</label><input id="cbValorContrato" value="${esc(c.valorContrato||c.valor||'')}" ${c.locacaoId?'readonly':''}></div><div><label>Valor atualizado do boleto</label><input id="cbValorAtualizado" value="${esc(c.valorAtualizado||'')}" placeholder="Opcional: juros/multa calculados externamente"></div></div><label>Observação</label><textarea id="cbObs">${esc(c.observacao||'')}</textarea>`,`<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarCobranca('${id}')">Salvar</button>`);window.__editCobLoc=c.locacaoId||'';setTimeout(atualizarLocacoesCobranca,0)}
function atualizarLocacoesCobranca(){const cli=$('cbCli')?.value,sel=$('cbLoc');if(!sel)return;const current=window.__editCobLoc||sel.value,locs=active('locacoes').filter(l=>l.clienteId===cli);sel.innerHTML='<option value="">Sem vínculo</option>'+selectOptions(locs,current,l=>`${l.protocolo||l.id} · ${dateBR(l.inicio)} → ${dateBR(l.termino)} · ${brl((l.itens||[]).reduce((s,i)=>s+Number(i.valorMensal||0),0))}`);if(current)sel.value=current;preencherValorCobranca();window.__editCobLoc=''}
function preencherValorCobranca(){const l=find('locacoes',$('cbLoc')?.value),v=$('cbValorContrato');if(!v)return;if(l){v.value=(l.itens||[]).reduce((s,i)=>s+Number(i.valorMensal||0),0);v.readOnly=true}else v.readOnly=false}
async function salvarCobranca(id){const cli=$('cbCli').value,venc=$('cbVenc').value,valor=num($('cbValorContrato').value),locId=$('cbLoc').value;if(!cli||!venc||!valor||!$('cbComp').value)return alert('Informe cliente, competência, vencimento e valor.');const l=find('locacoes',locId),obj={clienteId:cli,locacaoId:locId,locacaoProtocolo:l?.protocolo||'',competencia:$('cbComp').value,vencimento:venc,valorContrato:valor,valorAtualizado:num($('cbValorAtualizado').value)||null,valor,observacao:$('cbObs').value.trim(),ativo:true,arquivado:false};if(id){await setDoc(COLS.cobrancas,id,obj);await audit('editar','Cobranças',id,`Cobrança ${obj.competencia} atualizada.`)}else{const nid=await addDoc(COLS.cobrancas,obj);await audit('criar','Cobranças',nid,`Cobrança ${obj.competencia} criada para ${clientName(cli)}.`)}fecharModal();await refresh('Cobrança salva.')}
function registrarPagamento(id){const c=find('cobrancas',id),base=c.valorAtualizado||c.valorContrato||c.valor;abrirModal('Registrar pagamento',`<p><b>${esc(clientName(c.clienteId))}</b></p><p>Contrato: ${brl(c.valorContrato||c.valor)}${c.valorAtualizado?` · Atualizado: <b>${brl(c.valorAtualizado)}</b>`:''}</p><div class="grid2"><div><label>Data real do pagamento *</label><input id="pgData" type="date" value="${todayISO()}"></div><div><label>Valor pago *</label><input id="pgValor" value="${esc(base)}"></div></div><label class="check-item"><input id="pgMesmo" type="checkbox" checked onchange="if(this.checked)$('pgValor').value='${esc(base)}'"> Mesmo valor da cobrança</label><label>Observação</label><textarea id="pgObs"></textarea>`,`<button class="btn ghost" onclick="fecharModal()">Cancelar</button><button class="btn" onclick="salvarPagamento('${id}')">Confirmar</button>`)}
async function gerarCobrancasMes(mes){const locs=active('locacoes').filter(l=>l.status==='Ativa'&&(!l.inicio||l.inicio.slice(0,7)<=mes)&&(!l.termino||l.termino.slice(0,7)>=mes));let n=0;for(const l of locs){if(data.cobrancas.some(c=>c.locacaoId===l.id&&c.competencia===mes&&!isArchived(c)))continue;const valor=(l.itens||[]).reduce((s,i)=>s+Number(i.valorMensal||0),0);if(!valor)continue;await addDoc(COLS.cobrancas,{clienteId:l.clienteId,locacaoId:l.id,locacaoProtocolo:l.protocolo||'',competencia:mes,vencimento:dueDateForMonth(mes,l.diaVencimento||15),valorContrato:valor,valor,valorAtualizado:null,observacao:'Gerada a partir da locação ativa.',ativo:true,arquivado:false});n++}await audit('gerar_mes','Cobranças',mes,`${n} cobranças geradas para ${mes}.`);await refresh(`${n} cobrança(s) gerada(s).`)}

function signaturePng(data){
  if(!data)return'';try{const d=typeof data==='string'?JSON.parse(data):data,w=Math.max(1,Number(d.w)||500),h=Math.max(1,Number(d.h)||180),canvas=document.createElement('canvas');canvas.width=900;canvas.height=260;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='#123d6b';ctx.lineWidth=4;ctx.lineCap='round';ctx.lineJoin='round';const scale=Math.min((canvas.width-40)/w,(canvas.height-30)/h),ox=(canvas.width-w*scale)/2,oy=(canvas.height-h*scale)/2;(d.strokes||[]).forEach(st=>{if(st.length<2)return;ctx.beginPath();st.forEach((p,i)=>{const x=ox+(Number(p.x)||0)*scale,y=oy+(Number(p.y)||0)*scale;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()});return canvas.toDataURL('image/png')}catch(e){console.warn('assinatura png',e);return''}
}
function signatureBlock(data,label,meta=[]){const png=signaturePng(data);return `<div class="pdf-sign">${png?`<img src="${png}" alt="Assinatura">`:'<div class="pdf-sign-space"></div>'}<div class="pdf-line"><b>${esc(label)}</b>${meta.filter(Boolean).map(x=>`<br>${esc(x)}`).join('')}</div></div>`}
function documentSignatures(d){const techMeta=[d.assinaturaTecnicoNome,d.assinaturaTecnicoMatricula?`Matrícula: ${d.assinaturaTecnicoMatricula}`:'',d.assinaturaTecnicoFuncao||''],clientMeta=[d.assinaturaClienteNome||d.clienteNome||''];return `<div class="pdf-signatures">${signatureBlock(d.assinaturaTecnicoVetorial,'Representante / Safety Equipamentos',techMeta)}${signatureBlock(d.assinaturaClienteVetorial,'Cliente / responsável',clientMeta)}</div>`}
function aplicarAssinaturasDocumento(html,d){const bloco=documentSignatures(d);return html.includes('<div class="pdf-footer">')?html.replace('<div class="pdf-footer">',bloco+'<div class="pdf-footer">'):html+bloco}
function assinaturaCompleta(d){const req=d.assinaturasNecessarias||[];return req.every(x=>x==='tecnico'?!!d.assinaturaTecnicoVetorial:x==='cliente'?!!d.assinaturaClienteVetorial:true)}
function documentStatus(d){const req=d.assinaturasNecessarias||[];if(req.length&&!assinaturaCompleta(d))return'Pendente assinatura';if(d.pdfGeradoEm)return'Emitido';return req.length?'Assinado':'Preparado'}
function documentContext(d){let clienteId=d.clienteId||'',serial=d.serial||'',tech=d.assinaturaTecnicoNome||'';if(d.entidade==='locacao'){const l=find('locacoes',d.entidadeId);clienteId=l?.clienteId||clienteId;serial=(l?.itens||[]).map(i=>i.serialSnapshot).join(' ')}if(d.entidade==='assistencia'){const a=find('assistencias',d.entidadeId);clienteId=a?.clienteId||clienteId;serial=a?.serial||serial}if(d.entidade==='movimento'){const m=find('movimentos',d.entidadeId);clienteId=m?.clienteId||clienteId;serial=[find('equipamentos',m?.equipamentoAnteriorId)?.serial,find('equipamentos',m?.equipamentoNovoId)?.serial,find('equipamentos',m?.equipamentoId)?.serial].filter(Boolean).join(' ')}return{cliente:clientName(clienteId),serial,tech}}
function documentSearchText(d){const c=documentContext(d);return [d.protocolo,d.tipo,d.modeloVersao,d.referencia,c.cliente,c.serial,c.tech,documentStatus(d),d.criadoEm].join(' ')}
function viewDocumentos(){const all=active('documentos').sort((a,b)=>(b.criadoEm||'').localeCompare(a.criadoEm||'')),pending=all.filter(d=>documentStatus(d)==='Pendente assinatura'),history=all.filter(d=>documentStatus(d)!=='Pendente assinatura'),tab=window.__docTab||'pendentes',rows=tab==='pendentes'?pending:history;return `<div class="card"><div class="row"><div><h2>Documentos</h2><p class="hint">O PDF não é armazenado. O sistema mantém dados, versão do modelo e assinaturas vetoriais para regeneração.</p></div></div><div class="tabs"><button class="tab ${tab==='pendentes'?'active':''}" onclick="window.__docTab='pendentes';render()">Pendências (${pending.length})</button><button class="tab ${tab==='historico'?'active':''}" onclick="window.__docTab='historico';render()">Histórico (${history.length})</button></div><input class="search" placeholder="Pesquisar data, cliente, série, técnico, protocolo, tipo ou status..." oninput="filterTable('docTable',this.value)">${rows.length?`<table id="docTable"><thead><tr><th>Documento</th><th>Cliente / Referência</th><th>Assinaturas</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(d=>{const c=documentContext(d),req=d.assinaturasNecessarias||[];return `<tr data-search="${esc(documentSearchText(d))}"><td><b>${esc(d.protocolo||d.id)}</b><br>${esc(d.tipo)}<br><span class="muted">Modelo ${esc(d.modeloVersao||'—')} · ${dateTimeBR(d.criadoEm)}</span></td><td><b>${esc(c.cliente)}</b><br><span class="muted">${esc(c.serial||d.referencia||'')}</span></td><td>${req.includes('tecnico')?(d.assinaturaTecnicoVetorial?tag('Técnico ✓','ok'):tag('Técnico pendente','warn')):''} ${req.includes('cliente')?(d.assinaturaClienteVetorial?tag('Cliente ✓','ok'):tag('Cliente pendente','warn')):''}${!req.length?tag('Sem assinatura obrigatória','info'):''}</td><td>${tag(documentStatus(d),documentStatus(d)==='Pendente assinatura'?'warn':'ok')}</td><td><div class="inline-actions">${req.includes('tecnico')&&!d.assinaturaTecnicoVetorial?`<button class="btn small ghost" onclick="assinarDocumento('${d.id}','tecnico')">Assinar técnico</button>`:''}${req.includes('cliente')&&!d.assinaturaClienteVetorial?`<button class="btn small ghost" onclick="assinarDocumento('${d.id}','cliente')">Assinar cliente</button>`:''}<button class="btn small" onclick="reabrirDocumento('${d.id}')">Gerar PDF</button></div></td></tr>`}).join('')}</tbody></table>`:empty(tab==='pendentes'?'Nenhum documento com assinatura pendente.':'Nenhum documento no histórico.')}</div>`}

function openSignature(target){signatureTarget=target;signatureStrokes=[];signatureCurrentStroke=null;$('signatureTitle').textContent=target.title;$('signatureHint').textContent=target.hint||'Assine abaixo.';$('signatureModal').classList.remove('hidden');setTimeout(resizeSignatureCanvas,50)}
async function salvarAssinatura(){if(!signatureTarget)return;const pts=signatureStrokes.reduce((n,s)=>n+s.length,0);if(pts<4)return alert('Faça a assinatura antes de salvar.');try{const payload=JSON.stringify({w:Math.round(signatureCaptureSize.w),h:Math.round(signatureCaptureSize.h),strokes:signatureStrokes.map(st=>st.map(p=>({x:+p.x.toFixed(1),y:+p.y.toFixed(1)})))}),extra={};extra[signatureTarget.field]=payload;extra[`${signatureTarget.field}Em`]=nowISO();extra[`${signatureTarget.field}ColetadaPor`]=currentUser.uid;extra[`${signatureTarget.field}ColetadaPorNome`]=currentUser.nome;if(signatureTarget.field==='assinaturaTecnicoVetorial'){extra.assinaturaTecnicoNome=currentUser.nome;extra.assinaturaTecnicoMatricula=currentUser.matricula||'';extra.assinaturaTecnicoFuncao=currentUser.funcao||''}if(signatureTarget.field==='assinaturaClienteVetorial'){let nome='';if(signatureTarget.collection===COLS.documentos){const d=find('documentos',signatureTarget.id);nome=d?.clienteNome||documentContext(d||{}).cliente||''}if(signatureTarget.collection===COLS.movimentos){const m=find('movimentos',signatureTarget.id);nome=clientName(m?.clienteId)}extra.assinaturaClienteNome=nome}await setDoc(signatureTarget.collection,signatureTarget.id,extra);await audit('assinatura','Documentos',signatureTarget.id,`${signatureTarget.title} registrada eletronicamente.`);fecharAssinatura();await refresh('Assinatura salva.')}catch(e){alert('Não foi possível salvar a assinatura: '+e.message)}}
function assinarDocumento(docId,tipo){const d=find('documentos',docId);if(!d)return;const cliente=tipo==='cliente';openSignature({collection:COLS.documentos,id:docId,field:cliente?'assinaturaClienteVetorial':'assinaturaTecnicoVetorial',title:cliente?'Assinatura do cliente / responsável':'Assinatura do técnico responsável',hint:cliente?`Entregue o aparelho ao cliente/responsável de ${documentContext(d).cliente} para assinatura.`:'Assine abaixo. Nome, matrícula e função serão vinculados ao documento.'})}
function perguntarAssinaturaClienteMovimento(mid){openSignature({collection:COLS.movimentos,id:mid,field:'assinaturaClienteVetorial',title:'Assinatura do cliente',hint:'Entregue o aparelho ao cliente para assinatura. A operação permanecerá salva mesmo se a assinatura for cancelada.'})}

