async function criarEGerarDocumento(opts){try{requireOnline();let existing=findExistingDocument(opts.entidade,opts.entidadeId,opts.modeloTipo);if(existing){await refresh(null,false);return abrirDocumentoPreparado(existing.id)}const model=modelForType(opts.modeloTipo),protocolo=await nextProtocol('DOC'),docObj={protocolo,tipo:opts.tipo,modeloTipo:opts.modeloTipo,modeloId:model?.id||'',modeloVersao:model?.versao||'1.0',referencia:opts.referencia,entidade:opts.entidade,entidadeId:opts.entidadeId,clienteId:opts.clienteId||'',clienteNome:opts.clienteNome||'',serial:opts.serial||'',assinaturasNecessarias:opts.assinaturasNecessarias||[],assinaturaClienteVetorial:opts.assinaturaClienteVetorial||'',assinaturaTecnicoVetorial:opts.assinaturaTecnicoVetorial||'',sigiloFinanceiro:opts.sigiloFinanceiro===true,html:opts.html,ativo:true,arquivado:false},did=await addDoc(COLS.documentos,docObj);await audit('preparar','Documentos',did,`${protocolo} — ${opts.tipo} preparado usando modelo v${docObj.modeloVersao}.`);await refresh(null,false);abrirDocumentoPreparado(did)}catch(e){console.error(e);alert('Não foi possível preparar o documento: '+e.message)}}
