function gerarDocumentoLocacao(id){const l=find('locacoes',id);if(!l)return;const long=l.tipoDocumento!=='30dias',modelType=long?'contrato_locacao':'comprovante_entrega',tipo=long?'Contrato de Locação de Equipamentos':'Comprovante de Entrega de Equipamento';criarEGerarDocumento({tipo,modeloTipo:modelType,referencia:`Locação ${l.protocolo||id}`,entidade:'locacao',entidadeId:id,clienteId:l.clienteId,clienteNome:clientName(l.clienteId),serial:(l.itens||[]).map(i=>i.serialSnapshot).join(', '),html:docLocacao(l,tipo),assinaturasNecessarias:['tecnico','cliente'],sigiloFinanceiro:true})}
function gerarComprovanteEntrada(id){const a=find('assistencias',id);if(!a)return;criarEGerarDocumento({tipo:'Comprovante de Entrada de Equipamento',modeloTipo:'entrada_assistencia',referencia:`Assistência ${a.protocolo||id}`,entidade:'assistencia',entidadeId:id,clienteId:a.clienteId,clienteNome:clientName(a.clienteId),serial:a.serial,html:docEntradaAssistencia(a),assinaturasNecessarias:['tecnico','cliente'],sigiloFinanceiro:false})}
function gerarDocumentoAssistencia(id){const a=find('assistencias',id);abrirModal('Documentos da assistência',`<p>Atendimento <b>${esc(a.protocolo||id)}</b></p><div class="grid2"><button class="btn ghost" onclick="fecharModal();gerarComprovanteEntrada('${id}')">Comprovante de entrada</button><button class="btn ghost" onclick="fecharModal();gerarDocAssistTipo('${id}','orcamento')">Orçamento</button><button class="btn ghost" onclick="fecharModal();gerarDocAssistTipo('${id}','relatorio_manutencao')">Relatório de manutenção</button><button class="btn ghost" onclick="fecharModal();gerarDocAssistTipo('${id}','recibo')">Recibo</button></div>`)}
function gerarDocAssistTipo(id,tipo){const a=find('assistencias',id);if(!a)return;const cfg={orcamento:{nome:'Orçamento',html:docOrcamento(a),req:['tecnico']},relatorio_manutencao:{nome:'Relatório de Manutenção',html:docRelatorio(a),req:['tecnico']},recibo:{nome:'Recibo',html:docRecibo(a),req:['tecnico']}}[tipo];criarEGerarDocumento({tipo:cfg.nome,modeloTipo:tipo,referencia:`Assistência ${a.protocolo||id}`,entidade:'assistencia',entidadeId:id,clienteId:a.clienteId,clienteNome:clientName(a.clienteId),serial:a.serial,html:cfg.html,assinaturasNecessarias:cfg.req,sigiloFinanceiro:false})}
function gerarDocumentoMovimento(id){const m=find('movimentos',id);if(!m)return;const sub=m.tipo==='Substituição',modelType=sub?'termo_substituicao':'termo_emprestimo',sigilo=!!m.locacaoId;criarEGerarDocumento({tipo:sub?'Termo de Substituição de Equipamento':'Termo de Empréstimo',modeloTipo:modelType,referencia:`Movimento ${id}`,entidade:'movimento',entidadeId:id,clienteId:m.clienteId,clienteNome:clientName(m.clienteId),serial:[find('equipamentos',m.equipamentoAnteriorId)?.serial,find('equipamentos',m.equipamentoNovoId||m.equipamentoId)?.serial].filter(Boolean).join(', '),html:docMovimento(m),assinaturasNecessarias:['tecnico','cliente'],assinaturaClienteVetorial:m.assinaturaClienteVetorial||'',sigiloFinanceiro:sigilo})}
function gerarAditivoResponsavel(locId,movId){const l=find('locacoes',locId),m=find('movimentos',movId);if(!l||!m)return;criarEGerarDocumento({tipo:'Termo de Alteração de Responsável',modeloTipo:'aditivo_responsavel',referencia:`Locação ${l.protocolo||locId}`,entidade:'movimento',entidadeId:movId,clienteId:l.clienteId,clienteNome:clientName(l.clienteId),serial:(l.itens||[]).map(i=>i.serialSnapshot).join(', '),html:docAditivoResponsavel(l,m),assinaturasNecessarias:['tecnico','cliente'],sigiloFinanceiro:true})}
async function waitImages(root){const imgs=[...root.querySelectorAll('img')].filter(i=>!i.complete);await Promise.all(imgs.map(img=>new Promise(r=>{img.onload=img.onerror=r})))}
async function exportPdf(html,name){const area=$('printArea');area.innerHTML=html;area.style.display='block';const el=area.firstElementChild;try{await waitImages(el);if(document.fonts?.ready)await document.fonts.ready;if(window.html2pdf){const blob=await html2pdf().set({margin:[10,10,10,10],filename:name,pagebreak:{mode:['css','legacy'],avoid:['tr','.pdf-signatures','.pdf-meta']},image:{type:'jpeg',quality:.98},html2canvas:{scale:2,useCORS:true,backgroundColor:'#ffffff',scrollY:0,windowWidth:900},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'}}).from(el).outputPdf('blob');const file=new File([blob],name,{type:'application/pdf'});if(navigator.canShare?.({files:[file]})&&confirm('PDF gerado. Deseja compartilhar agora pelo WhatsApp, e-mail ou outro aplicativo?'))await navigator.share({files:[file],title:name,text:'Documento Safety Equipamentos'});else downloadBlob(blob,name);return true}else{window.print();return true}}catch(e){console.error(e);alert('Não foi possível gerar o PDF automaticamente. Será aberta a impressão do navegador.');window.print();return false}finally{area.innerHTML='';area.style.display='none'}}
async function reabrirDocumento(id){const d=find('documentos',id);if(!d)return;const ok=await exportPdf(aplicarAssinaturasDocumento(d.html,d),`${fileSafe(d.tipo)}_${d.protocolo||id}.pdf`);if(ok){try{await setDoc(COLS.documentos,id,{pdfGeradoEm:nowISO(),pdfGeradoPor:currentUser.uid});await audit('gerar_pdf','Documentos',id,`${d.protocolo||id} gerado localmente em PDF.`);await refresh(null,false)}catch(e){console.warn(e)}}}

function viewAuditoria(){if(!isAdmin())return empty('Acesso restrito.');const rows=allRecords('auditoria').sort((a,b)=>(b.em||'').localeCompare(a.em||'')).slice(0,1000),users=[...new Set(rows.map(x=>x.nome||x.uid).filter(Boolean))].sort();return `<div class="card"><h2>Auditoria</h2><p class="hint">Rastreamento das principais ações. Os registros de auditoria não podem ser alterados ou excluídos pela operação normal.</p><div class="grid4 audit-filters"><div><label>Usuário</label><select id="audUser" onchange="filterAuditTable()"><option value="">Todos</option>${users.map(u=>`<option>${esc(u)}</option>`).join('')}</select></div><div><label>Data inicial</label><input id="audFrom" type="date" onchange="filterAuditTable()"></div><div><label>Data final</label><input id="audTo" type="date" onchange="filterAuditTable()"></div><div><label>Busca</label><input id="audQ" placeholder="Módulo, ação, cliente..." oninput="filterAuditTable()"></div></div>${rows.length?`<table id="audTable"><thead><tr><th>Data/hora</th><th>Usuário</th><th>Módulo</th><th>Ação</th><th>Resumo</th></tr></thead><tbody>${rows.map(a=>`<tr data-user="${esc(a.nome||a.uid||'')}" data-date="${esc((a.em||'').slice(0,10))}" data-search="${esc([a.module,a.action,a.summary,a.itemId].join(' '))}"><td>${dateTimeBR(a.em)}</td><td>${esc(a.nome||a.uid||'')}</td><td>${esc(a.module||'')}</td><td>${esc(a.action||'')}</td><td>${esc(a.summary||'')}</td></tr>`).join('')}</tbody></table>`:empty('Nenhum evento de auditoria.')}</div>`}
function filterAuditTable(){const user=$('audUser')?.value||'',from=$('audFrom')?.value||'',to=$('audTo')?.value||'',q=normalize($('audQ')?.value||'');document.querySelectorAll('#audTable tbody tr').forEach(tr=>{const d=tr.dataset.date||'',ok=(!user||tr.dataset.user===user)&&(!from||d>=from)&&(!to||d<=to)&&(!q||normalize(tr.dataset.search||tr.textContent).includes(q));tr.style.display=ok?'':'none'})}

window.addEventListener('load',()=>setTimeout(updateConnectionBadge,50));
